// Run `git` or `gh`. The process Claude Code runs in can have an older PATH than the machine: an app that was
// started before they were installed keeps its old environment until it is restarted. So if the program cannot be
// started on Windows, try its standard install folder before giving up, and remember whichever worked.
// What could go wrong: the fallback paths are fixed strings under %ProgramFiles%, the arguments are passed as an
// array with no shell, and a path that stops working is forgotten and looked up again.
const WINDOWS_INSTALLS: Record<'git' | 'gh', (programFiles: string) => string[]> = {
  gh: pf => [`${pf}\\GitHub CLI\\gh.exe`],
  git: pf => [`${pf}\\Git\\cmd\\git.exe`, `${pf}\\Git\\bin\\git.exe`],
}
const exeFound = new Map<string, string>()

// The lookup logic is in exe.ts (it tells a timeout from a program that is not there by how long the call ran, since
// the API gives no wording for either); this wires it to the engine.
const runExe = ($: Engine, name: 'git' | 'gh', args: string[], timeoutMs: number) =>
  runExeWith({
    run: (argv, timeout) => $.process.run(argv, { timeoutMs: timeout }),
    name,
    args,
    timeoutMs,
    found: exeFound,
    fallbacks: async () => {
      const programFiles = (await $.env.get('OS')) === 'Windows_NT' ? await $.env.get('ProgramFiles') : undefined

      return programFiles ? WINDOWS_INSTALLS[name](programFiles) : []
    },
  })

async function git($: Engine, args: string[]) {
  try {
    const r = await runExe($, 'git', args, 10_000)
    return r.exitCode === 0 ? r.stdout : null
  } catch {
    return null
  }
}

async function heartbeat($: Engine) {
  if (!ctx.dir || !ctx.selfId) return
  let costUsd: number | null = null
  let contextPct: number | null = null
  const now = Date.now()
  try {
    const u = await $.session.usage()
    costUsd = u.cost?.usd ?? null
    contextPct = u.context.percent ?? null
    trackLimits(u.rateLimits, now)
  } catch {}
  for (const step of crossedSteps(ctx.lastContextPct, contextPct)) {
    note($, { at: now, tone: step >= 90 ? 'bad' : 'warn', text: `this session's context is at ${step}%${step >= 75 ? ': /compact soon' : ''}` }, step >= 75)
  }
  if (contextPct !== null) ctx.lastContextPct = contextPct
  for (const [file, at] of ctx.edits) if (now - at > EDIT_WINDOW_MS) ctx.edits.delete(file)
  me.editing = [...ctx.edits.keys()]
  me.risky = ctx.risky && now - ctx.risky.at < RISKY_WINDOW_MS ? ctx.risky.label : ''
  me.ctxTrend = ctx.ctxTrend
  me.cacheHitPct = ctx.cacheHit
  me.plan = ctx.plan
  me.planAt = ctx.planAt
  me.sources = ctx.sources
  me.turnFiles = ctx.turnFiles
  me.lastTest = ctx.lastTest
  const row: SessionRow = { ...me, costUsd, contextPct, updatedAt: now }
  await $.fs.write(`${ctx.dir}/${ctx.selfId}.json`, JSON.stringify(row)).catch(() => undefined)
}

// Claude Code's own record of running sessions: one <pid>.json per process,
// written whether or not this plugin is loaded. Only *.json is read; the
// .key files beside them are not ours to touch.
type RegistryEntry = {
  pid: number
  sessionId: string
  cwd: string
  startedAt: number
  name?: string
  nameSource?: string
  waitingFor?: string
  entrypoint?: string
  status?: string
  statusUpdatedAt?: number
  updatedAt?: number
}

const stateOf = (status: string | undefined): SessionState => {
  const s = (status ?? '').toLowerCase()
  if (/wait|permission|input|blocked|ask/.test(s)) return 'waiting'
  if (/busy|running|working|thinking/.test(s)) return 'running'
  return 'idle'
}

const appOf = (entrypoint: string | undefined) =>
  !entrypoint ? '' : entrypoint === 'claude-desktop' ? 'desktop' : entrypoint === 'cli' ? 'cli' : entrypoint.replace(/^claude-/, '')

const gitCache = new Map<string, { at: number; repo: string; branch: string }>()

// A readable name for sessions whose registry name is only derived from their
// folder ("2025-2a"): the AI title Claude Code writes into the transcript, else
// the last prompt. Only those two record types are kept; the rest is dropped.
const titleCache = new Map<string, { at: number; title: string }>()
const TITLE_TTL_MS = 60_000
const READ_LIMIT = 4 * 1024 * 1024 - 64 * 1024

const titleIn = (text: string) => {
  let title = ''
  let prompt = ''
  for (const line of text.split(/\r?\n/)) {
    if (!line.includes('-title"') && !line.includes('"last-prompt"')) continue
    try {
      const d = JSON.parse(line) as { type?: string; aiTitle?: string; customTitle?: string; lastPrompt?: string }
      if (d.type === 'custom-title' && d.customTitle) title = d.customTitle
      else if (d.type === 'ai-title' && d.aiTitle) title = d.aiTitle
      else if (d.type === 'last-prompt' && d.lastPrompt) prompt = d.lastPrompt
    } catch {}
  }
  const tidy = (s: string) => s.replace(/\s+/g, ' ').trim()

  return title ? tidy(title) : prompt ? `“${cut(tidy(prompt), 48)}”` : ''
}

async function titleOf($: Engine, reg: RegistryEntry): Promise<string> {
  const hit = titleCache.get(reg.sessionId)
  if (hit && Date.now() - hit.at < TITLE_TTL_MS) return hit.title
  const path = `${ctx.projectsDir}/${reg.cwd.replace(/[^A-Za-z0-9]/g, '-')}/${reg.sessionId}.jsonl`
  let title = ''
  try {
    const stat = await $.fs.stat(path)
    if (stat.size <= READ_LIMIT) {
      title = titleIn(await $.fs.read(path))
    } else {
      for (const argv of [
        ['grep', '-a', '-F', '-e', '-title"', '-e', '"last-prompt"', path],
        ['findstr', '/L', 'ai-title custom-title last-prompt', path],
      ]) {
        try {
          const r = await $.process.run(argv, { timeoutMs: 10_000 })
          if (r.exitCode === 0) {
            title = titleIn(r.stdout)
            break
          }
        } catch {}
      }
    }
  } catch {}
  titleCache.set(reg.sessionId, { at: Date.now(), title })

  return title
}

async function livePids($: Engine): Promise<Set<number> | null> {
  try {
    const r = await $.process.run(['tasklist', '/FO', 'CSV', '/NH'], { timeoutMs: 10_000 })
    if (r.exitCode === 0) {
      return new Set(lines(r.stdout).map(l => Number(l.split('","')[1])).filter(n => n > 0))
    }
  } catch {}
  try {
    const r = await $.process.run(['ps', '-A', '-o', 'pid='], { timeoutMs: 10_000 })
    if (r.exitCode === 0) return new Set(lines(r.stdout).map(Number).filter(n => n > 0))
  } catch {}

  return null
}

async function whereIs($: Engine, cwd: string) {
  const hit = gitCache.get(cwd)
  if (hit && Date.now() - hit.at < 30_000) return hit
  const [top, branch] = await Promise.all([
    git($, ['-C', cwd, 'rev-parse', '--show-toplevel']),
    git($, ['-C', cwd, 'rev-parse', '--abbrev-ref', 'HEAD']),
  ])
  const found = { at: Date.now(), repo: base(top?.trim() || cwd), branch: branch?.trim() || '' }
  gitCache.set(cwd, found)

  return found
}

async function readHeartbeats($: Engine): Promise<Map<string, SessionRow>> {
  const entries = await $.fs.list(ctx.dir).catch(() => [])
  const now = Date.now()
  const beats = new Map<string, SessionRow>()
  for (const f of entries) {
    if (f.kind !== 'file' || !f.name.endsWith('.json')) continue
    if (f.mtimeMs > 0 && now - f.mtimeMs > STALE_MS) continue
    try {
      const row = JSON.parse(await $.fs.read(`${ctx.dir}/${f.name}`)) as SessionRow
      if (row.id && row.state !== 'ended' && now - row.updatedAt < STALE_MS) beats.set(row.id, row)
    } catch {}
  }

  return beats
}

async function readSessions($: Engine): Promise<SessionRow[]> {
  const [entries, alive, beats] = await Promise.all([
    $.fs.list(ctx.registryDir).catch(() => []),
    livePids($),
    readHeartbeats($),
  ])
  const rows: SessionRow[] = []
  const seen = new Set<string>()
  for (const f of entries) {
    if (f.kind !== 'file' || !f.name.endsWith('.json')) continue
    let reg: RegistryEntry
    try {
      reg = JSON.parse(await $.fs.read(`${ctx.registryDir}/${f.name}`)) as RegistryEntry
    } catch {
      continue
    }
    if (!reg.sessionId || seen.has(reg.sessionId)) continue
    if (alive && !alive.has(reg.pid)) continue
    seen.add(reg.sessionId)
    const beat = beats.get(reg.sessionId)
    const where = beat?.branch ? { repo: beat.repo, branch: beat.branch } : await whereIs($, reg.cwd)
    const isDerived = !reg.name || reg.nameSource === 'derived'
    const name = (isDerived ? await titleOf($, reg) : '') || reg.name || ''
    rows.push({
      id: reg.sessionId,
      name,
      waitingFor: reg.status === 'waiting' || beat?.state === 'waiting' ? (reg.waitingFor ?? '') : '',
      app: appOf(reg.entrypoint),
      hasPlugin: beat !== undefined,
      cwd: reg.cwd,
      repo: where.repo,
      branch: where.branch,
      state: beat ? beat.state : stateOf(reg.status),
      stateSince: beat?.stateSince ?? reg.statusUpdatedAt ?? reg.startedAt,
      startedAt: reg.startedAt,
      lastTool: beat?.lastTool ?? '',
      costUsd: beat?.costUsd ?? null,
      contextPct: beat?.contextPct ?? null,
      updatedAt: beat?.updatedAt ?? reg.updatedAt ?? reg.startedAt,
      stuck: beat?.stuck ?? '',
      editing: beat?.editing ?? [],
      risky: beat?.risky ?? '',
      ctxTrend: beat?.ctxTrend ?? [],
      cacheHitPct: beat?.cacheHitPct ?? null,
      summary: beat?.summary ?? '',
      plan: beat?.plan ?? null,
      planAt: beat?.planAt ?? 0,
      sources: beat?.sources ?? [],
      turnFiles: beat?.turnFiles ?? [],
      lastTest: beat?.lastTest ?? null,
    })
  }
  for (const beat of beats.values()) {
    if (!seen.has(beat.id)) rows.push(beat)
  }
  const order: Record<SessionState, number> = { waiting: 0, running: 1, idle: 2, ended: 3 }

  return rows.sort((a, b) => order[a.state] - order[b.state] || b.startedAt - a.startedAt)
}

// ---------------------------------------------------------------------------
// Monitoring: limits, events and alerts
// ---------------------------------------------------------------------------
function trackLimits(readings: ReadonlyArray<{ kind: string; percentUsed: number; resetsAt?: string }>, now: number) {
  ctx.limits = readings.map(r => {
    const kept = [...(ctx.limitSamples.get(r.kind) ?? []), { at: now, pct: r.percentUsed }].filter(s => now - s.at <= LIMIT_WINDOW_MS)
    // A reset drops the percentage: start the pace over from there.
    const resetAt = kept.findLastIndex((s, i) => i > 0 && s.pct < kept[i - 1].pct)
    const fromReset = resetAt > 0 ? kept.slice(resetAt) : kept
    ctx.limitSamples.set(r.kind, fromReset)
    const resetsAt = r.resetsAt ? Date.parse(r.resetsAt) : NaN
    return { kind: limitLabel(r.kind), pct: r.percentUsed, resetsAt: Number.isFinite(resetsAt) ? resetsAt : null, etaMs: runwayMs(fromReset) }
  })
}

function note($: Engine, event: EventRow, isAlert: boolean) {
  ctx.events = [event, ...ctx.events].slice(0, EVENTS_KEPT)
  if (isAlert && ctx.alertsOn) {
    $.ui.toast(event.text, { timeoutMs: 6000 })
    // Plays where the host has a player (macOS terminals, the desktop app); silent elsewhere.
    void $.audio.play(SOUND).catch(() => undefined)
  }
}

// ---------------------------------------------------------------------------
// Disk space, once a minute
// ---------------------------------------------------------------------------
async function readDisks($: Engine) {
  try {
    const r = ctx.isWindows
      ? await $.process.run(
          [
            'powershell',
            '-NoProfile',
            '-Command',
            'Get-PSDrive -PSProvider FileSystem | ForEach-Object { "$($_.Name) $([int64]$_.Free) $([int64]$_.Used)" }',
          ],
          { timeoutMs: 15_000 },
        )
      : await $.process.run(['df', '-Pk'], { timeoutMs: 10_000 })
    if (r.exitCode !== 0) return
    ctx.disks = ctx.isWindows ? parseWindowsDisks(r.stdout) : parseDf(r.stdout)
  } catch {
    return
  }
  const now = Date.now()
  for (const d of ctx.disks) {
    const isLow = isDiskLow(d)
    if (isLow && !ctx.lowDisks.has(d.name)) {
      note($, { at: now, tone: 'bad', text: `disk ${d.name} is low: ${bytes(d.freeBytes)} free` }, true)
    }
    if (isLow) ctx.lowDisks.add(d.name)
    else ctx.lowDisks.delete(d.name)
  }
}

// ---------------------------------------------------------------------------
// Agents: every live session's subagents, from the transcripts Claude Code keeps
// (<projects>/<slug>/<session>/subagents/agent-<id>.jsonl and .meta.json).
// ---------------------------------------------------------------------------
const agentCache = new Map<string, { stamp: string; sum: AgentSummary; meta: AgentMeta }>()

async function readAgents($: Engine, sessions: readonly SessionRow[]): Promise<AgentRow[]> {
  const now = Date.now()
  const rows: AgentRow[] = []
  for (const s of sessions) {
    const dir = `${ctx.projectsDir}/${slugOf(s.cwd)}/${s.id}/subagents`
    const entries = await $.fs.list(dir).catch(() => [])
    const byName = new Map(entries.map(f => [f.name, f] as const))
    for (const f of entries) {
      const m = /^agent-(.+)\.jsonl$/.exec(f.name)
      if (!m || f.kind !== 'file') continue
      const id = m[1]
      const metaFile = byName.get(`agent-${id}.meta.json`)
      const lastActive = Math.max(f.mtimeMs, metaFile?.mtimeMs ?? 0)
      const stamp = `${f.mtimeMs}:${f.size}:${metaFile?.mtimeMs ?? 0}`
      let hit = agentCache.get(`${s.id}/${id}`)
      if (!hit || hit.stamp !== stamp) {
        let meta: AgentMeta = {}
        let sum: AgentSummary = { startedAt: null, steps: 0, doing: '', isFinished: false }
        try {
          if (metaFile) meta = JSON.parse(await $.fs.read(`${dir}/${metaFile.name}`)) as AgentMeta
        } catch {}
        try {
          if (f.size <= READ_LIMIT) sum = summarizeAgent(await $.fs.read(`${dir}/${f.name}`))
        } catch {}
        hit = { stamp, sum, meta }
        agentCache.set(`${s.id}/${id}`, hit)
      }
      const state = agentStateOf(hit.meta, hit.sum, lastActive, now, true)
      if ((state === 'done' || state === 'stopped') && now - lastActive > AGENT_RECENT_MS) continue
      rows.push({
        id,
        sessionId: s.id,
        sessionName: s.name || s.repo,
        type: hit.meta.agentType ?? 'agent',
        description: hit.meta.description || 'subagent',
        state,
        isBackground: hit.meta.requestShape === 'background',
        startedAt: hit.sum.startedAt ?? lastActive,
        lastActive,
        doing: hit.sum.doing,
        steps: hit.sum.steps,
      })
    }
  }
  const order = { working: 0, quiet: 1, done: 2, stopped: 3 } as const

  return rows.sort((a, b) => order[a.state] - order[b.state] || b.lastActive - a.lastActive)
}

async function readGit($: Engine): Promise<GitInfo | null> {
  const branch = (await git($, ['rev-parse', '--abbrev-ref', 'HEAD']))?.trim()
  if (!branch) return null
  const [status, counts, stash, head, refs, wt, diff] = await Promise.all([
    git($, ['status', '--porcelain']),
    git($, ['rev-list', '--left-right', '--count', '@{u}...HEAD']),
    git($, ['stash', 'list']),
    git($, ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD']),
    git($, ['for-each-ref', '--sort=-committerdate', '--count=8', '--format=%(refname:short)|%(committerdate:relative)', 'refs/heads']),
    git($, ['worktree', 'list', '--porcelain']),
    git($, ['diff', '--shortstat', 'HEAD']),
  ])
  const [behind, ahead] = counts ? counts.trim().split(/\s+/).map(Number) : [0, 0]
  const baseRef = head?.trim().replace(/^origin\//, '') || 'main'
  const merged = new Set(lines((await git($, ['branch', '--merged', baseRef, '--format=%(refname:short)'])) ?? ''))
  const branches: BranchRow[] = lines(refs ?? '').map(l => {
    const [name, age] = l.split('|')
    return { name, age: (age ?? '').replace(' ago', ''), isMerged: merged.has(name) && name !== baseRef && name !== branch }
  })
  const worktrees: WorktreeRow[] = []
  for (const l of lines(wt ?? '')) {
    if (l.startsWith('worktree ')) worktrees.push({ path: l.slice(9), branch: '(detached)' })
    else if (l.startsWith('branch ') && worktrees.length > 0) {
      worktrees[worktrees.length - 1].branch = l.slice(7).replace('refs/heads/', '')
    }
  }

  return {
    branch,
    upstream: counts !== null,
    ahead: ahead || 0,
    behind: behind || 0,
    dirty: lines(status ?? '').length,
    stashes: lines(stash ?? '').length,
    base: baseRef,
    branches,
    worktrees,
    ...parseShortstat(diff ?? ''),
  }
}

const runGh = ($: Engine, args: string[], timeoutMs: number) => runExe($, 'gh', args, timeoutMs)

async function readPrs($: Engine): Promise<PrInfo> {
  try {
    const r = await runGh(
      $,
      [
        'api',
        'graphql',
        '-f',
        `query=${PR_QUERY}`,
        '-f',
        'mine=is:pr is:open author:@me archived:false',
        '-f',
        'review=is:pr is:open review-requested:@me archived:false',
      ],
      20_000,
    )
    if (r.exitCode !== 0) throw new Error(lines(r.stderr)[0] ?? 'gh failed')
    const data = (JSON.parse(r.stdout) as { data?: { mine?: { nodes?: GhPr[] }; review?: { nodes?: GhPr[] } } }).data
    const keep = (nodes: GhPr[] | undefined) => (nodes ?? []).filter(p => typeof p.number === 'number').map(toRow)
    return {
      error: null,
      mine: keep(data?.mine?.nodes),
      toReview: keep(data?.review?.nodes).sort((a, b) => b.ageDays - a.ageDays),
      fetchedAt: Date.now(),
    }
  } catch (err) {
    const msg = String((err as Error)?.message ?? err)
    const error = /ENOENT|not found|cannot start|not recognized/i.test(msg)
      ? 'gh CLI not found: install it, then run gh auth login'
      : cut(msg, 70)
    return { error, mine: [], toReview: [], fetchedAt: Date.now() }
  }
}

// One small model call after a finished turn; the label is written to this session's status file.
async function summarize($: Engine, answer: string) {
  if (!ctx.summariesOn || ctx.isSummarizing) return
  ctx.isSummarizing = true
  try {
    const r = await $.model.complete({
      model: 'haiku',
      system: SUMMARY_SYSTEM,
      prompt: summaryPrompt(ctx.lastPrompt, answer, ctx.calls.map(c => c.label)),
      maxTokens: 40,
      timeoutMs: 20_000,
    })
    if (r.isAnswered) {
      me.summary = tidySummary(r.text)
      await heartbeat($)
      await publish($, undefined)
    }
  } catch {
    // A failed label is not worth an alert; the next turn tries again.
  } finally {
    ctx.isSummarizing = false
  }
}

// A refresh that fails must never stop a command from answering or a hook from finishing. The error is
// written to ~/.claude/dev-dash/last-error.txt (and only the latest), so a failure can be read afterwards.
async function logError($: Engine, where: string, err: unknown) {
  try {
    if (!ctx.root) return
    const detail = String((err as Error)?.stack ?? err).slice(0, 1500)
    await $.fs.write(`${ctx.root}/last-error.txt`, `${new Date().toISOString()} ${where}\n${detail}\n`)
  } catch {}
}

async function publishNow($: Engine, gitInfo: GitInfo | null | undefined, sample = false) {
  const sessions = await readSessions($)
  const agents = await readAgents($, sessions)
  if (sample) {
    const calls = ctx.toolCalls
    ctx.toolCalls = 0
    await update($, activity, h => pushActivity(h, sessions, agents, calls))
  }
  const now = Date.now()
  const mine = ctx.prs && !ctx.prs.error ? ctx.prs.mine : null
  const muting = { snoozed: (await read($, snoozed)) ?? {}, dismissed: (await read($, dismissed)) ?? [], now }
  for (const c of changesBetween(ctx.seen, sessions, agents, mine, ctx.selfId, now, ctx.isFirstLook)) {
    // A row you snoozed or dismissed in the pane stays in the feed but stops making noise.
    const isMutedRow = c.itemId !== undefined && isMuted(muting, c.itemId)
    note($, { at: c.at, tone: c.tone, text: c.text }, c.isAlert && !isMutedRow)
  }
  ctx.seen = remember(sessions, agents, mine)
  ctx.isFirstLook = false
  await update($, snap, s => {
    const next: Snapshot = {
      selfId: ctx.selfId,
      sessions,
      agents,
      limits: ctx.limits,
      events: ctx.events,
      alertsOn: ctx.alertsOn,
      bandOn: ctx.bandOn,
      summariesOn: ctx.summariesOn,
      paneOpen: ctx.isOpen,
      disks: ctx.disks,
      nowPlaying: ctx.nowPlaying,
      spotifyOn: ctx.spotifyOn,
      focusOn: ctx.focusOn,
      theme: ctx.theme,
      beatStyle: ctx.beatStyle,
      buddyName: ctx.buddyName,
      git: gitInfo === undefined ? (s?.git ?? null) : gitInfo,
      prs: ctx.prs,
      watches: ctx.watches,
      iconStyle: ctx.iconStyle,
      updatedAt: Date.now(),
    }
    return next
  })
}

async function publish($: Engine, gitInfo: GitInfo | null | undefined, sample = false) {
  try {
    await publishNow($, gitInfo, sample)
  } catch (err) {
    await logError($, 'publish', err)
  }
}

async function setState($: Engine, state: SessionState) {
  if (me.state === state) return
  me.state = state
  me.stateSince = Date.now()
  await heartbeat($)
  await publish($, undefined)
}

// Files this turn edited, with lines added/removed against HEAD. A file git has no diff for
// but lists as untracked is new: all of its lines count as added.
async function readTurnFiles($: Engine): Promise<ChangedFile[]> {
  const files: ChangedFile[] = []
  for (const file of [...ctx.turnEdits.values()].slice(-TURN_FILES_KEPT)) {
    const out = await git($, ['diff', '--numstat', 'HEAD', '--', file])
    // git could not answer (not found, not a repository, or the file is outside one): the file was still edited
    // this turn, so it is listed, with its line counts marked as unknown rather than left out.
    if (out === null) {
      files.push({ path: file, added: 0, removed: 0, counted: false })
      continue
    }
    const diff = parseNumstat(out)[0]
    if (diff) {
      files.push({ path: file, added: diff.added, removed: diff.removed })
      continue
    }
    const isNew = ((await git($, ['ls-files', '--others', '--exclude-standard', '--', file])) ?? '').trim() !== ''
    if (!isNew) continue
    try {
      files.push({ path: file, added: countLines(await $.fs.read(file)), removed: 0 })
    } catch {}
  }

  return files
}

// Keep only the newest HANDOFFS_KEPT notes. There is no delete in the file API, so this asks the OS;
// staleNotes only ever names files that look exactly like the ones we write.
async function pruneHandoffs($: Engine) {
  const entries = await $.fs.list(ctx.handoffDir).catch(() => [])
  for (const name of staleNotes(entries.filter(f => f.kind === 'file').map(f => f.name))) {
    // Run in the notes folder and pass only the bare name (it has matched NOTE_NAME: no spaces, separators,
    // wildcards or leading dash). Passing a full path through cmd's re-parsing is what could split on a
    // home directory with a space.
    await $.process
      .run(ctx.isWindows ? ['cmd', '/c', 'del', '/q', name] : ['rm', '-f', name], { cwd: ctx.handoffDir, timeoutMs: 10_000 })
      .catch(() => undefined)
  }
}

// ---------------------------------------------------------------------------
// /dash-watch: pull requests the person asked to keep an eye on
// ---------------------------------------------------------------------------
const isWatchRow = (v: unknown): v is WatchRow =>
  !!v && typeof v === 'object' && typeof (v as WatchRow).id === 'string' && typeof (v as WatchRow).number === 'number' && typeof (v as WatchRow).repo === 'string'

// The list lives in the plugin store, so every session sees the same one; each cycle starts from it.
async function loadWatches($: Engine): Promise<WatchRow[]> {
  const v = await $.store.get('watches').catch(() => undefined)

  return Array.isArray(v) ? v.filter(isWatchRow) : []
}

// How each kind is read: the gh subcommand, the fields asked for, and the function that turns the answer into a reading.
const GH_READ: Record<WatchKind, { args: string[]; fields: string; read: (json: unknown) => Reading | null }> = {
  pr: { args: ['pr', 'view'], fields: PR_FIELDS, read: readPr },
  issue: { args: ['issue', 'view'], fields: ISSUE_FIELDS, read: readIssue },
  run: { args: ['run', 'view'], fields: RUN_FIELDS, read: readRun },
}

async function readWatch($: Engine, w: WatchRow) {
  const g = GH_READ[w.kind] ?? GH_READ.pr
  try {
    const r = await runGh($, [...g.args, String(w.number), '--repo', w.repo, '--json', g.fields], 20_000)
    return r.exitCode === 0 ? g.read(JSON.parse(r.stdout)) : null
  } catch {
    return null
  }
}

// One look at every live watch: no faster than WATCH_EVERY_MS unless forced (adding a watch takes its baseline).
// A change after the baseline fires the watch: a line in the event feed and a mark in the section. Never a toast.
async function pollWatches($: Engine, force: boolean) {
  const now = Date.now()
  if (!force && now - ctx.watchPolledAt < WATCH_EVERY_MS) return
  ctx.watchPolledAt = now
  let list = (await loadWatches($)).filter(w => !isExpired(w, now))
  for (const w of pollable(list, now)) {
    const r = await readWatch($, w)
    if (!r) continue
    const next = stepWatch(w, r, now)
    if (next.firedAt > w.firedAt) {
      const tone = /failing|failed|conflict/.test(next.fired) ? 'bad' : /merged|passed|ready/.test(next.fired) ? 'ok' : 'info'
      note($, { at: now, tone, text: `watch ${watchName(w)} ${w.repo}: ${next.fired}` }, false)
    }
    list = list.map(x => (x.id === w.id ? next : x))
  }
  ctx.watches = list
  await $.store.set('watches', list).catch(() => undefined)
}

async function tick($: Engine, withPrs: boolean) {
  try {
    await tickNow($, withPrs)
  } catch (err) {
    await logError($, 'tick', err)
  }
}

// What Spotify on this machine is playing, read with a local command. Only while the pane is open and the
// Entertainment tab is the one showing, and no more often than every NOW_PLAYING_EVERY_MS. On Windows each read starts
// a PowerShell, so it is not made more often than a track name needs. Returns whether the reading changed.
const NOW_PLAYING_EVERY_MS = 10_000

async function readNowPlaying($: Engine) {
  const now = Date.now()
  if (now - ctx.nowPlayingAt < NOW_PLAYING_EVERY_MS) return false
  ctx.nowPlayingAt = now
  const before = `|`
  try {
    const r = await $.process.run(nowPlayingCommand(ctx.platform), { timeoutMs: 8000 })
    ctx.nowPlaying = parseNowPlaying(ctx.platform, r.stdout, r.exitCode, now)
  } catch {
    ctx.nowPlaying = unavailable(now)
  }

  return `|` !== before
}

async function tickNow($: Engine, withPrs: boolean) {
  const g = await readGit($)
  if (g) me.branch = g.branch
  // Only while a turn runs: turn.complete already took the final numbers, and an idle session
  // should not keep spawning git for files it edited minutes ago.
  if (me.state === 'running' && ctx.turnEdits.size > 0) ctx.turnFiles = await readTurnFiles($)
  await heartbeat($)
  if (withPrs) ctx.prs = await readPrs($)
  const showing = ctx.isOpen ? await read($, tab) : null
  // The list is read from the store inside, so a watch another session added is picked up too.
  if (ctx.isOpen) await pollWatches($, false)
  if (ctx.ticks % DISK_EVERY_TICKS === 0) await readDisks($)
  await publish($, g, true)
  // Spotify last, and not waited for: a slow read (up to its 8 s limit) must not hold up the PR and watch polling or this
  // tick's publish. If the track changed, it is published once the read is back.
  if (ctx.spotifyOn && isTab(showing) && showing === 'entertainment') {
    void readNowPlaying($)
      .then(changed => (changed ? publish($, g) : undefined))
      .catch(() => undefined)
  }
}

// What `a`, `r` and `q` do. The typed commands and the footer keys run the same code. (A plugin cannot run its
// own slash commands through $.command.run, which skips the calling plugin's hooks, so the keys call these.)
// Spotify is opt-in. Off means nothing is read at all: no command runs, and the card says how to turn it on.
async function setSpotify($: Engine, arg: string) {
  const a = arg.trim().toLowerCase()
  ctx.spotifyOn = a === 'on' ? true : a === 'off' ? false : !ctx.spotifyOn
  await $.store.set('spotifyOn', ctx.spotifyOn).catch(() => undefined)
  ctx.nowPlaying = null
  ctx.nowPlayingAt = 0
  if (ctx.spotifyOn && ctx.isOpen && (await read($, tab)) === 'entertainment') await readNowPlaying($)
  await publish($, undefined)

  return ctx.spotifyOn
    ? 'Spotify is on: the Entertainment tab shows what the Spotify app on this machine is playing. Turn it off with /dash-spotify off.'
    : 'Spotify is off. Nothing is read.'
}

// Load the buddy pack the header is set to use (a JSON file made by tools/make-buddy.py). Null when it is not a pack.
async function loadBuddy($: Engine) {
  setBuddy(null)
  if (ctx.beatStyle !== 'buddy' || !NAME_OK.test(ctx.buddyName)) return false
  const text = await $.fs.read(`${ctx.root}/buddy/${ctx.buddyName}.json`).catch(() => '')
  const pack = text ? parsePack(text) : null
  setBuddy(pack)

  return pack !== null
}

// /dash-beat: `line` (the default red line), `buddy [name]`, a bare name, `list`, or nothing to switch between them.
async function setBeat($: Engine, arg: string) {
  const [word = '', second = ''] = arg.trim().split(/\s+/)
  const w = word.toLowerCase()
  if (w === 'list') {
    const found = (await $.fs.list(`${ctx.root}/buddy`).catch(() => []))
      .filter(f => f.kind === 'file' && f.name.endsWith('.json'))
      .map(f => f.name.slice(0, -5))
      .filter(n => NAME_OK.test(n))

    return found.length
      ? `Buddies: ${found.join(', ')}. Use /dash-beat buddy <name>, or /dash-beat line for the red line.`
      : 'No buddies yet. Make one with tools/make-buddy.py from a .sprite file or animated GIFs (see the README), then /dash-beat list.'
  }
  if (w === 'line' || (w === '' && ctx.beatStyle === 'buddy')) {
    ctx.beatStyle = 'line'
    setBuddy(null)
    await $.store.set('beatStyle', 'line').catch(() => undefined)
    await publish($, undefined)

    return 'The header shows the claude beat line.'
  }
  const name = w === '' || w === 'buddy' ? second || ctx.buddyName : w
  if (!name) return 'Which buddy? /dash-beat list shows the ones you have.'
  if (!NAME_OK.test(name)) return 'A buddy name is letters, digits, - and _ only.'
  const was = { style: ctx.beatStyle, name: ctx.buddyName }
  ctx.beatStyle = 'buddy'
  ctx.buddyName = name
  if (!(await loadBuddy($))) {
    ctx.beatStyle = was.style
    ctx.buddyName = was.name
    await loadBuddy($)

    return `No buddy called "${name}" (or its file is not a pack this version can play). /dash-beat list shows the ones you have.`
  }
  await $.store.set('beatStyle', 'buddy').catch(() => undefined)
  await $.store.set('buddyName', name).catch(() => undefined)
  await publish($, undefined)

  return `The header shows ${name}. /dash-beat line goes back to the red line.`
}

// /dash-theme: no argument or `next` cycles, `list` names them, a name picks one. The footer button cycles.
async function setTheme($: Engine, arg: string) {
  const a = arg.trim().toLowerCase()
  if (a === 'list') return `Themes: ${THEMES.map(t => `${t.id} (${t.blurb})`).join(' · ')}. Now: ${ctx.theme}.`
  const picked = a && a !== 'next' ? themeByName(a) : undefined
  if (a && a !== 'next' && !picked) return `No theme called "${arg.trim()}". Try /dash-theme list.`
  ctx.theme = picked ? picked.id : nextTheme(ctx.theme)
  await $.store.set('theme', ctx.theme).catch(() => undefined)
  await publish($, undefined)
  const t = themeByName(ctx.theme)

  return `Theme: ${t?.label ?? ctx.theme}. ${t?.blurb ?? ''}${ctx.theme === 'auto' ? '' : ' (The exact colours want a truecolor terminal.)'}`
}

// The focus fold is on by default: while something urgently needs you, the other cards fold to one line each.
async function setFocus($: Engine, arg: string) {
  const a = arg.trim().toLowerCase()
  ctx.focusOn = a === 'on' ? true : a === 'off' ? false : !ctx.focusOn
  await $.store.set('focusOn', ctx.focusOn).catch(() => undefined)
  await publish($, undefined)

  return ctx.focusOn
    ? 'Focus is on: while something needs you, the other cards fold to one line each. Open one with its arrow.'
    : 'Focus is off: every card stays as you left it.'
}

async function setAlerts($: Engine, arg: string) {
  const a = arg.trim().toLowerCase()
  ctx.alertsOn = a === 'on' ? true : a === 'off' ? false : !ctx.alertsOn
  await $.store.set('alertsOn', ctx.alertsOn).catch(() => undefined)
  await publish($, undefined)

  return `Dashboard alerts ${ctx.alertsOn ? 'on' : 'off'}.`
}

async function refreshNow($: Engine) {
  titleCache.clear()
  gitCache.clear()
  await tick($, true)

  return `Dashboard refreshed${ctx.prs?.error ? `; PRs: ${ctx.prs.error}` : ''}.`
}

async function closePane($: Engine) {
  ctx.isOpen = false
  await update($, paneOpen, () => false)
  await $.ui.close({ id: PANE })
  await publish($, undefined)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const ran = await next(e)
    ctx.selfId = await $.session.id()
    const home = ((await $.env.get('USERPROFILE')) || (await $.env.get('HOME')) || '').replace(/\\/g, '/')
    const config = ((await $.env.get('CLAUDE_CONFIG_DIR')) || `${home}/.claude`).replace(/\\/g, '/')
    ctx.root = `${config}/dev-dash`
    ctx.dir = `${config}/dev-dash/sessions`
    ctx.handoffDir = `${config}/dev-dash/handoffs`
    ctx.registryDir = `${config}/sessions`
    ctx.projectsDir = `${config}/projects`
    me.id = ctx.selfId
    me.cwd = await $.session.cwd()
    const top = (await git($, ['rev-parse', '--show-toplevel']))?.trim()
    me.repo = base(top || me.cwd)
    try {
      me.startedAt = (await $.session.usage()).startedAt
    } catch {}

    await $.command.register({ name: 'dash', description: 'Open the developer dashboard pane' })
    await $.command.register({ name: 'dash-hide', description: 'Hide the developer dashboard pane' })
    await $.command.register({ name: 'dash-alerts', description: 'Turn dashboard toasts on or off (on | off, or toggle)' })
    await $.command.register({ name: 'dash-band', description: 'Show or hide the dev-dash line above the prompt (on | off, or toggle)' })
    const stored = await $.store.get('alertsOn').catch(() => undefined)
    if (typeof stored === 'boolean') ctx.alertsOn = stored
    const storedBand = await $.store.get('bandOn').catch(() => undefined)
    if (typeof storedBand === 'boolean') ctx.bandOn = storedBand
    await $.command.register({ name: 'dash-beat', description: 'What the header draws: line (the claude beat, default) | buddy <name> (an animated character) | list' })
    const storedBeat = await $.store.get('beatStyle').catch(() => undefined)
    const storedBuddy = await $.store.get('buddyName').catch(() => undefined)
    if (typeof storedBuddy === 'string' && NAME_OK.test(storedBuddy)) ctx.buddyName = storedBuddy
    if (storedBeat === 'buddy' || storedBeat === 'line') ctx.beatStyle = storedBeat
    await loadBuddy($)
    await $.command.register({ name: 'dash-theme', description: 'Colour theme: auto (default) | claude | nord | neon | crt | light | mono, or no name to cycle; list shows them' })
    const storedTheme = await $.store.get('theme').catch(() => undefined)
    if (isTheme(storedTheme)) ctx.theme = storedTheme
    await $.command.register({ name: 'dash-focus', description: 'Fold the other cards to one line while something needs you (on | off, or toggle; on by default)' })
    const storedFocus = await $.store.get('focusOn').catch(() => undefined)
    if (typeof storedFocus === 'boolean') ctx.focusOn = storedFocus
    await $.command.register({ name: 'dash-spotify', description: 'Show what Spotify is playing on the Entertainment tab (on | off, or toggle; off by default)' })
    const storedSpotify = await $.store.get('spotifyOn').catch(() => undefined)
    if (typeof storedSpotify === 'boolean') ctx.spotifyOn = storedSpotify
    await $.command.register({ name: 'dash-summaries', description: 'Write a one-line summary per session after each turn (on | off; uses a small model call per turn)' })
    const storedSummaries = await $.store.get('summariesOn').catch(() => undefined)
    if (typeof storedSummaries === 'boolean') ctx.summariesOn = storedSummaries
    await $.command.register({ name: 'dash-icons', description: 'Icons in the Watching boxes: emoji (any font, default) | nerd (the official GitHub mark, needs a Nerd Font) | ascii' })
    const storedIcons = parseIconStyle(String(await $.store.get('iconStyle').catch(() => '')))
    if (storedIcons) ctx.iconStyle = storedIcons
    await $.command.register({ name: 'dash-handoff', description: 'Write a handoff note when a session compacts (on | off, or toggle)' })
    const storedHandoff = await $.store.get('handoffOn').catch(() => undefined)
    if (typeof storedHandoff === 'boolean') ctx.handoffOn = storedHandoff
    await $.command.register({ name: 'dash-watch', description: 'Keep an eye on a pull request: pr <number or URL> | list | clear <number|all>' })
    ctx.watches = (await loadWatches($)).filter(w => !isExpired(w, Date.now()))
    await $.command.register({ name: 'dash-refresh', description: 'Refresh the dashboard now, PRs included' })
    ctx.isWindows = (await $.env.get('OS')) === 'Windows_NT'
    if (ctx.isWindows) ctx.platform = 'windows'
    else {
      const uname = await $.process.run(['uname', '-s'], { timeoutMs: 5000 }).catch(() => undefined)
      ctx.platform = uname?.stdout.trim() === 'Darwin' ? 'mac' : 'linux'
    }
    // A reload of the mod starts this module over; the host's state remembers the pane was open.
    ctx.isOpen = (await read($, paneOpen)) === true
    await tick($, ctx.isOpen)
    // A half-second beat while the pane is open: the claude beat's tip blinks and the buddy steps with it. Only a
    // counter changes: no data is collected.
    $.clock.every(500, async () => {
      if (ctx.isOpen) await update($, blink, v => ((v ?? 0) + 1) % 1_000_000)
    })
    // A sprite buddy on the terminal is a Raster: repaint it in place about eight times a second, so it walks and
    // flies smoothly without redrawing the pane. Nothing runs unless the pane is open and showing one.
    $.clock.every(BUDDY_MS, async () => {
      const pack = getBuddy()
      const at = getStage()
      if (!ctx.isOpen || ctx.beatStyle !== 'buddy' || pack?.kind !== 'sprite' || !at) return
      await $.ui.blit({ requestId: PANE, key: 'buddy', cells: toRaster(drawScene(pack, at.mood, Date.now(), at.cols, at.rows)) }).catch(() => undefined)
    })
    $.clock.every(TICK_MS, async () => {
      ctx.ticks += 1
      await tick($, ctx.isOpen && (ctx.prs === null || ctx.ticks % PR_EVERY_TICKS === 0))
    })

    return ran
  })

  on('session.end', async ($, e, next) => {
    me.state = 'ended'
    await heartbeat($)

    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    ctx.turnEdits.clear()
    ctx.turnFiles = []
    await setState($, 'running')

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const ran = await next(e)
    ctx.cacheHit = cacheHitPct(e.usage) ?? ctx.cacheHit
    try {
      const pct = (await $.session.usage()).context.percent
      if (typeof pct === 'number') ctx.ctxTrend = [...ctx.ctxTrend, Math.round(pct)].slice(-12)
    } catch {}
    if (!e.agentId && e.durationMs >= LONG_TASK_MS) {
      note($, { at: Date.now(), tone: 'ok', text: `this session finished a ${Math.round(e.durationMs / 60_000)}m task` }, true)
    }
    if (ctx.turnEdits.size > 0) ctx.turnFiles = await readTurnFiles($)
    await setState($, 'idle')
    if (!e.agentId && !e.isAborted) void summarize($, e.answer)

    return ran
  })

  on('prompt.submit', async ($, e, next) => {
    ctx.lastPrompt = e.text

    return next(e)
  })

  on('command.run', { command: 'dash-summaries' }, async ($, e) => {
    const arg = (e.args ?? '').trim().toLowerCase()
    ctx.summariesOn = arg === 'on' ? true : arg === 'off' ? false : !ctx.summariesOn
    await $.store.set('summariesOn', ctx.summariesOn)
    if (!ctx.summariesOn) me.summary = ''
    await heartbeat($)
    await publish($, undefined)

    return {
      text: ctx.summariesOn
        ? 'Session summaries on: one small Haiku call after each finished turn. Turn off with /dash-summaries off.'
        : 'Session summaries off.',
    }
  })

  on('tool.check', async ($, e, next) => {
    const r = await next(e)
    if (r.decision === 'ask') await setState($, 'waiting')

    return r
  })

  on('tool.call', async ($, e, next) => {
    ctx.toolCalls += 1
    const input = e as unknown as Record<string, unknown>
    me.lastTool = stepLabel(e.tool, input)
    if (e.tool === 'AskUserQuestion') {
      await setState($, 'waiting')
      const r = await next(e)
      await setState($, 'running')
      return r
    }
    await setState($, 'running')
    if ((e.tool === 'Bash' || e.tool === 'PowerShell') && typeof input.command === 'string') {
      const label = riskyReason(input.command)
      if (label) ctx.risky = { label, at: Date.now() }
    }
    if (['Edit', 'Write', 'MultiEdit', 'NotebookEdit'].includes(e.tool)) {
      const file = input.file_path ?? input.notebook_path
      if (typeof file === 'string') {
        ctx.edits.set(normPath(file), Date.now())
        ctx.turnEdits.set(normPath(file), file)
      }
    }
    if (e.tool === 'TodoWrite') {
      const plan = planOf(input)
      if (plan) {
        ctx.plan = plan
        ctx.planAt = Date.now()
      }
    }
    const source = sourceOf(e.tool, input, Date.now())
    if (source) ctx.sources = addSource(ctx.sources, source)

    let isOk = false
    let wasCut = false
    try {
      const ran = await next(e)
      const shape = ran as { deny?: string; isError?: boolean; result?: { interrupted?: boolean } }
      isOk = !shape.deny && !shape.isError && !shape.result?.interrupted
      wasCut = !!shape.deny || !!shape.result?.interrupted
      return ran
    } finally {
      ctx.calls = [...ctx.calls, { key: callKey(e.tool, input), label: stepLabel(e.tool, input), isOk, at: Date.now() }].slice(-20)
      me.stuck = stuckReason(ctx.calls)
      // A test run's outcome. The result has no exit code field; a failing command comes back as an error.
      // A call that was denied or interrupted never finished a run, so it leaves the badge alone.
      if ((e.tool === 'Bash' || e.tool === 'PowerShell') && typeof input.command === 'string' && !wasCut) {
        ctx.lastTest = testRunOf(input.command, isOk, Date.now()) ?? ctx.lastTest
      }
    }
  })

  on('command.run', { command: 'dash-refresh' }, async $ => ({ text: await refreshNow($) }))

  // The footer keys. The press is taken here, so the Button's own onPress (a no-op) never runs.
  on('ui.press', { plugin: 'dev-dash', element: 'key-refresh' }, async ($, e) => {
    await refreshNow($)

    return { element: e.element }
  })
  on('ui.press', { plugin: 'dev-dash', element: 'spotify-toggle' }, async ($, e) => {
    await setSpotify($, '')

    return { element: e.element }
  })
  on('ui.press', { plugin: 'dev-dash', element: 'key-theme' }, async ($, e) => {
    await setTheme($, '')

    return { element: e.element }
  })
  on('ui.press', { plugin: 'dev-dash', element: 'key-alerts' }, async ($, e) => {
    await setAlerts($, '')

    return { element: e.element }
  })
  on('ui.press', { plugin: 'dev-dash', element: 'key-close' }, async ($, e) => {
    await closePane($)

    return { element: e.element }
  })

  // Closed some other way (the pane's own close, or Claude Code itself): stop polling GitHub.
  on('ui.close', async ($, e, next) => {
    if (e.id === PANE) {
      ctx.isOpen = false
      await update($, paneOpen, () => false)
    }

    return next(e)
  })

  on('command.run', { command: 'dash-band' }, async ($, e) => {
    const arg = (e.args ?? '').trim().toLowerCase()
    ctx.bandOn = arg === 'on' ? true : arg === 'off' ? false : !ctx.bandOn
    await $.store.set('bandOn', ctx.bandOn)
    await publish($, undefined)

    return { text: `Dashboard line above the prompt ${ctx.bandOn ? 'on' : 'off'}.` }
  })

  on('command.run', { command: 'dash-alerts' }, async ($, e) => ({ text: await setAlerts($, e.args ?? '') }))
  on('command.run', { command: 'dash-beat' }, async ($, e) => ({ text: await setBeat($, e.args ?? '') }))
  on('command.run', { command: 'dash-theme' }, async ($, e) => ({ text: await setTheme($, e.args ?? '') }))
  on('command.run', { command: 'dash-focus' }, async ($, e) => ({ text: await setFocus($, e.args ?? '') }))
  on('command.run', { command: 'dash-spotify' }, async ($, e) => ({ text: await setSpotify($, e.args ?? '') }))

  on('command.run', { command: 'dash-watch' }, async ($, e) => {
    const cmd = parseWatchArgs(e.args ?? '')
    const now = Date.now()
    ctx.watches = (await loadWatches($)).filter(w => !isExpired(w, now))
    if (cmd.cmd === 'help') return { text: `${cmd.reason} ${WATCH_HELP}` }
    if (cmd.cmd === 'list') {
      const rows = ctx.watches.map((w, i) => `${i + 1}. ${watchName(w)} ${w.repo} · ${w.detail || 'waiting for the first look'}${w.firedAt ? ` · ${w.fired}` : ''}`)

      return { text: rows.length ? rows.join('\n') : `Nothing watched. ${WATCH_HELP}` }
    }
    if (cmd.cmd === 'clear') {
      const r = clearWatches(ctx.watches, cmd.which)
      ctx.watches = r.list
      await $.store.set('watches', r.list).catch(() => undefined)
      await publish($, undefined)

      return { text: r.removed ? `Cleared ${r.removed === 1 ? 'that watch' : `${r.removed} watches`}.` : 'No watch with that number. /dash-watch list shows them.' }
    }
    // Add. A bare number means this session's repository, as gh knows it.
    let spec = cmd.spec
    if (!spec.repo) {
      let name = ''
      try {
        const r = await runGh($, ['repo', 'view', '--json', 'nameWithOwner'], 15_000)
        if (r.exitCode === 0) name = String((JSON.parse(r.stdout) as { nameWithOwner?: string }).nameWithOwner ?? '')
      } catch {}
      if (!name) return { text: `I could not tell which repository #${spec.number} is in. Use owner/repo#${spec.number} or the GitHub URL.` }
      spec = { ...spec, repo: name }
    }
    const added = addWatch(ctx.watches, spec, now)
    if (added.error || !added.added) return { text: added.error }
    ctx.watches = added.list
    await $.store.set('watches', added.list).catch(() => undefined)
    await pollWatches($, true)
    await publish($, undefined)
    const w = ctx.watches.find(x => x.id === added.added?.id)

    // No reading yet means gh could not answer: not on PATH for this process, not logged in, or no such item.
    const unread = w?.detail ? '' : ` I could not read it just now: check that \`gh\` is installed, on your PATH and logged in (\`gh auth status\`), and that the ${spec.kind === 'pr' ? 'pull request' : spec.kind === 'issue' ? 'issue' : 'run'} exists. It will keep trying while the pane is open.`

    return { text: `Watching ${watchName(spec)} in ${spec.repo}${w?.detail ? ` (now ${w.detail})` : ''}. It is checked about once a minute while the dashboard pane is open, and drops off after 24 hours.${unread}` }
  })

  on('command.run', { command: 'dash-icons' }, async ($, e) => {
    const style = parseIconStyle(e.args ?? '')
    if (!style) {
      return { text: `Icons are ${ctx.iconStyle}. Choose one: ${ICON_STYLES.join(' | ')}. emoji works in any font; nerd draws the official GitHub mark and needs a Nerd Font set as your terminal font (nerdfonts.com), or it shows as an empty box; ascii is plain letters.` }
    }
    ctx.iconStyle = style
    await $.store.set('iconStyle', style).catch(() => undefined)
    await publish($, undefined)

    return { text: `Icons: ${style}.${style === 'nerd' ? ' If the GitHub mark shows as an empty box, your terminal font is not a Nerd Font: use /dash-icons emoji.' : ''}` }
  })

  on('command.run', { command: 'dash-handoff' }, async ($, e) => {
    const arg = (e.args ?? '').trim().toLowerCase()
    ctx.handoffOn = arg === 'on' ? true : arg === 'off' ? false : !ctx.handoffOn
    await $.store.set('handoffOn', ctx.handoffOn)

    return {
      text: ctx.handoffOn
        ? `Handoff notes on: one short note in ${ctx.handoffDir || '~/.claude/dev-dash/handoffs'} each time a session compacts (newest ${HANDOFFS_KEPT} kept).`
        : 'Handoff notes off. Notes already written stay where they are.',
    }
  })

  // A handoff note whenever the main conversation compacts, for whoever picks the work up after.
  // `precompute` installs nothing and a subagent's own compaction is not this session's, so both are skipped.
  on('session.compact', async ($, e, next) => {
    const ran = await next(e)
    if (!ctx.handoffOn || e.agentId || e.trigger === 'precompute' || ran.skip !== undefined || !ctx.handoffDir || !ctx.selfId) return ran
    const at = Date.now()
    try {
      await $.fs.write(
        `${ctx.handoffDir}/${handoffName(at, ctx.selfId)}`,
        handoffNote({
          at,
          sessionId: ctx.selfId,
          name: me.name,
          repo: me.repo,
          branch: me.branch,
          cwd: me.cwd,
          trigger: e.trigger,
          tokensBefore: ran.tokensBefore,
          tokensAfter: ran.tokensAfter,
          plan: ctx.plan,
          lastTool: me.lastTool,
          files: me.editing,
          summary: ran.messages[0]?.text ?? '',
        }),
      )
      note($, { at, tone: 'info', text: 'saved a handoff note for this compaction' }, false)
      await pruneHandoffs($)
    } catch {}

    return ran
  })

  on('command.run', { command: 'dash' }, async $ => {
    ctx.isOpen = true
    await update($, paneOpen, () => true)
    // focus: the keys work as soon as the pane is up, with no ctrl+x tab first.
    await $.ui.open({ id: PANE, title: 'Dev dashboard', focus: true })
    if (ctx.disks.length === 0) void readDisks($)
    void tick($, true)

    return { text: 'Dashboard opened.' }
  })

  on('command.run', { command: 'dash-hide' }, async $ => {
    await closePane($)

    return { text: 'Dashboard hidden.' }
  })

  // The drawing lives in ./render.tsx (drop-in replacement for the old inline hook).
  registerDashPane(on, {
    onHide: () => {
      ctx.isOpen = false
    },
  })
}

files.hooks/monitor.ts:
// dev-dash: pure monitoring logic. Nothing here touches `$`, so every function
// can be tested on plain values.

import type { AgentRow, CiState, EventRow, PrRow, SessionRow, SessionState } from '../types'
import { ids } from './keys'

const baseName = (p: string) => p.replace(/[\\/]+$/, '').split(/[\\/]/).pop() ?? p
const oneLine = (s: string, n = 60) => {
  const t = s.replace(/\s+/g, ' ').trim()
  return t.length > n ? `${t.slice(0, n - 1)}…` : t
}

// ---------------------------------------------------------------------------
// What a tool call is doing, in a few words
// ---------------------------------------------------------------------------
export const toolDetail = (tool: string, input: Record<string, unknown> | undefined): string => {
  const s = (k: string) => (typeof input?.[k] === 'string' ? (input[k] as string) : '')
  switch (tool) {
    case 'Bash':
    case 'PowerShell':
      return oneLine(s('description') || s('command'), 50)
    case 'Read':
    case 'Edit':
    case 'Write':
    case 'MultiEdit':
    case 'NotebookEdit':
      return baseName(s('file_path') || s('notebook_path'))
    case 'Grep':
    case 'Glob':
      return oneLine(s('pattern'), 40)
    case 'WebSearch':
      return oneLine(s('query'), 50)
    case 'WebFetch': {
      const url = s('url')
      return oneLine(url.replace(/^https?:\/\//, ''), 50)
    }
    case 'Agent':
    case 'Task':
      return oneLine(s('description'), 50)
    case 'SendMessage':
      return s('to')
    default:
      return ''
  }
}

export const stepLabel = (tool: string, input?: Record<string, unknown>) => {
  const detail = toolDetail(tool, input)
  return detail ? `${tool}: ${detail}` : tool
}

// ---------------------------------------------------------------------------
// Subagent transcripts (<projects>/<slug>/<session>/subagents/agent-<id>.jsonl)
// ---------------------------------------------------------------------------
export type AgentSummary = {
  startedAt: number | null
  steps: number
  doing: string
  isFinished: boolean
}

type Block = { type?: string; name?: string; input?: Record<string, unknown> }
type Line = { type?: string; timestamp?: string; message?: { content?: unknown; stop_reason?: string } }

/** Reads an agent transcript: when it started, how many tool steps, its latest step, and whether it handed back. */
export const summarizeAgent = (text: string): AgentSummary => {
  let startedAt: number | null = null
  let steps = 0
  let doing = ''
  let isFinished = false
  for (const raw of text.split(/\r?\n/)) {
    if (!raw) continue
    let d: Line
    try {
      d = JSON.parse(raw) as Line
    } catch {
      continue
    }
    if (startedAt === null && d.timestamp) {
      const t = Date.parse(d.timestamp)
      if (Number.isFinite(t)) startedAt = t
    }
    if (d.type !== 'assistant') {
      if (d.type === 'user') isFinished = false
      continue
    }
    const blocks = Array.isArray(d.message?.content) ? (d.message?.content as Block[]) : []
    const uses = blocks.filter(b => b?.type === 'tool_use')
    if (uses.length === 0) {
      // A reply with no tool call ends the agent's turn.
      if (blocks.some(b => b?.type === 'text')) isFinished = true
      continue
    }
    steps += uses.length
    const last = uses[uses.length - 1]
    const tool = last.name ?? 'tool'
    isFinished = tool === 'SubagentHandback'
    doing = isFinished ? 'handed back its report' : stepLabel(tool, last.input)
  }

  return { startedAt, steps, doing, isFinished }
}

export type AgentMeta = {
  agentType?: string
  description?: string
  requestShape?: string
  stoppedByUser?: boolean
}

/** How long without a transcript write before a still-open agent counts as quiet rather than working. */
export const QUIET_AFTER_MS = 90_000

export const agentStateOf = (meta: AgentMeta, sum: AgentSummary, lastActive: number, now: number, isSessionAlive: boolean) => {
  if (meta.stoppedByUser) return 'stopped' as const
  if (sum.isFinished) return 'done' as const
  if (!isSessionAlive) return 'stopped' as const
  return now - lastActive < QUIET_AFTER_MS ? ('working' as const) : ('quiet' as const)
}

// ---------------------------------------------------------------------------
// Usage-limit runway
// ---------------------------------------------------------------------------
export type Sample = { at: number; pct: number }

/** Time until 100% at the pace seen across `samples` (oldest first); null when flat, falling, or too little history. */
export const runwayMs = (samples: readonly Sample[]): number | null => {
  if (samples.length < 2) return null
  const first = samples[0]
  const last = samples[samples.length - 1]
  const dt = last.at - first.at
  const dp = last.pct - first.pct
  if (dt < 120_000 || dp <= 0) return null
  return Math.max(0, ((100 - last.pct) / dp) * dt)
}

export const limitLabel = (kind: string) =>
  ({ five_hour: '5h', seven_day: '7d', seven_day_opus: '7d opus', seven_day_sonnet: '7d sonnet', spend_limit: 'spend' })[kind] ??
  kind.replace(/_/g, ' ')

// ---------------------------------------------------------------------------
// Stuck detection for this session's own tool calls
// ---------------------------------------------------------------------------
export type CallMark = { key: string; label: string; isOk: boolean; at: number }

export const callKey = (tool: string, input: Record<string, unknown> | undefined) => {
  const main = input?.command ?? input?.file_path ?? input?.pattern ?? input?.url ?? input?.query ?? ''
  return `${tool}|${typeof main === 'string' ? main : JSON.stringify(main)}`
}

/** '' when fine; otherwise why it looks stuck. `calls` is newest last. */
export const stuckReason = (calls: readonly CallMark[]): string => {
  const recent = calls.slice(-6)
  const last = recent[recent.length - 1]
  if (!last) return ''
  const tail3 = recent.slice(-3)
  if (tail3.length === 3 && tail3.every(c => c.key === last.key && !c.isOk)) {
    return `${last.label} failed ${tail3.length}× in a row`
  }
  if (recent.length === 6 && recent.every(c => c.key === last.key)) return `repeating ${last.label}`
  return ''
}

// ---------------------------------------------------------------------------
// Two sessions editing the same file
// ---------------------------------------------------------------------------
export type Collision = { file: string; sessions: string[] }

export const collisionsOf = (sessions: readonly SessionRow[]): Collision[] => {
  const byFile = new Map<string, string[]>()
  for (const r of sessions) {
    for (const f of r.editing ?? []) byFile.set(f, [...(byFile.get(f) ?? []), r.name || r.repo])
  }

  return [...byFile.entries()].filter(([, who]) => who.length > 1).map(([file, who]) => ({ file, sessions: who }))
}

// ---------------------------------------------------------------------------
// git diff --shortstat
// ---------------------------------------------------------------------------
export const parseShortstat = (s: string) => ({
  added: Number(/(\d+) insertion/.exec(s)?.[1] ?? 0),
  removed: Number(/(\d+) deletion/.exec(s)?.[1] ?? 0),
})

// ---------------------------------------------------------------------------
// Events: what changed between two snapshots
// ---------------------------------------------------------------------------
export type Seen = {
  sessions: Map<string, { state: SessionState; since: number; stuck: string; risky: string }>
  agents: Map<string, AgentRow['state']>
  ci: Map<number, CiState>
}

export const emptySeen = (): Seen => ({ sessions: new Map(), agents: new Map(), ci: new Map() })

/** `itemId` ties a change to a row in the Attention section, so snoozing or dismissing that row also silences its toast. */
export type Change = EventRow & { isAlert: boolean; itemId?: string }

/**
 * Compares the last view with the new one. `isAlert` marks what is worth a toast:
 * something now needs the person. The first call (empty `seen`) reports nothing.
 */
export const changesBetween = (
  seen: Seen,
  sessions: readonly SessionRow[],
  agents: readonly AgentRow[],
  mine: readonly PrRow[] | null,
  selfId: string,
  now: number,
  isFirst: boolean,
): Change[] => {
  const out: Change[] = []
  const name = (r: SessionRow) => r.name || `${r.repo}${r.branch ? `@${r.branch}` : ''}`

  for (const r of sessions) {
    const was = seen.sessions.get(r.id)
    if (!isFirst && was) {
      if (r.state === 'waiting' && was.state !== 'waiting' && r.id !== selfId) {
        out.push({ at: now, tone: 'warn', text: `${name(r)} needs ${r.waitingFor || 'you'}`, isAlert: true, itemId: ids.wait(r) })
      }
      if (r.state === 'idle' && was.state === 'running' && now - was.since > 60_000 && r.id !== selfId) {
        const isLong = now - was.since >= LONG_TASK_MS
        out.push({ at: now, tone: 'ok', text: `${name(r)} finished${isLong ? ` after ${Math.round((now - was.since) / 60_000)}m` : ''}`, isAlert: isLong })
      }
      if (r.risky && r.risky !== was.risky) {
        out.push({ at: now, tone: 'bad', text: `${name(r)} ran a risky command: ${r.risky}`, isAlert: true, itemId: ids.risky(r) })
      }
      if (r.stuck && r.stuck !== was.stuck) {
        out.push({ at: now, tone: 'bad', text: `${name(r)} may be stuck: ${r.stuck}`, isAlert: true, itemId: ids.stuck(r) })
      }
    }
    if (!isFirst && !was && r.id !== selfId) out.push({ at: now, tone: 'info', text: `${name(r)} started`, isAlert: false })
  }

  for (const a of agents) {
    const was = seen.agents.get(a.id)
    if (isFirst) continue
    if (!was && (a.state === 'working' || a.state === 'quiet')) {
      out.push({ at: now, tone: 'info', text: `agent started: ${a.description}`, isAlert: false })
    } else if (was && was !== a.state && a.state === 'done') {
      out.push({ at: now, tone: 'ok', text: `agent finished: ${a.description}`, isAlert: true })
    } else if (was && was !== a.state && a.state === 'stopped') {
      out.push({ at: now, tone: 'warn', text: `agent stopped: ${a.description}`, isAlert: false })
    }
  }

  for (const p of mine ?? []) {
    const was = seen.ci.get(p.number)
    if (isFirst || was === undefined || was === p.ci) continue
    if (p.ci === 'failing') out.push({ at: now, tone: 'bad', text: `#${p.number} CI went red`, isAlert: true, itemId: ids.ci(p) })
    else if (p.ci === 'passing' && was === 'failing') out.push({ at: now, tone: 'ok', text: `#${p.number} CI is green again`, isAlert: true })
  }

  return out
}

export const remember = (sessions: readonly SessionRow[], agents: readonly AgentRow[], mine: readonly PrRow[] | null): Seen => ({
  sessions: new Map(sessions.map(r => [r.id, { state: r.state, since: r.stateSince, stuck: r.stuck, risky: r.risky }] as const)),
  agents: new Map(agents.map(a => [a.id, a.state] as const)),
  ci: new Map((mine ?? []).map(p => [p.number, p.ci] as const)),
})

/** Context thresholds crossed upward since `last` (e.g. 48 → 77 crosses 50 and 75). */
export const CONTEXT_STEPS = [50, 75, 90] as const
export const crossedSteps = (last: number | null, now: number | null) =>
  last === null || now === null ? [] : CONTEXT_STEPS.filter(step => last < step && now >= step)

// ---------------------------------------------------------------------------
// Risky shell commands (flagged, never blocked)
// ---------------------------------------------------------------------------
const RISKY: ReadonlyArray<[RegExp, string]> = [
  [/\brm\s+(-[a-z]*r[a-z]*f|-[a-z]*f[a-z]*r|--recursive\s+--force|--force\s+--recursive)\b/i, 'rm -rf'],
  [/\bgit\s+push\b[^\n;&|]*\s(--force(?!-with-lease)|-f\b)/i, 'git push --force'],
  [/\bgit\s+reset\s+--hard\b/i, 'git reset --hard'],
  [/\bgit\s+clean\s+-[a-z]*f/i, 'git clean -f'],
  [/\bgit\s+(checkout|restore)\s+(--\s+)?\.(\s|$)/i, 'discard all changes'],
  [/\bgit\s+branch\s+-D\b/, 'git branch -D'],
  [/\bdrop\s+(database|table|schema)\b/i, 'DROP'],
  [/\btruncate\s+table\b/i, 'TRUNCATE'],
  [/\bRemove-Item\b[^\n]*-Recurse[^\n]*-Force|\bRemove-Item\b[^\n]*-Force[^\n]*-Recurse/i, 'Remove-Item -Recurse -Force'],
  [/\b(del|erase)\s+(\/[a-z]\s+)*\/s\b/i, 'del /s'],
  [/\brd\s+\/s\b|\brmdir\s+\/s\b/i, 'rmdir /s'],
  [/\bmkfs(\.\w+)?\b|\bformat\s+[a-z]:/i, 'format disk'],
  [/\bdd\s+if=.*\bof=\/dev\//i, 'dd to a device'],
  [/\bchmod\s+-R\s+777\b/i, 'chmod -R 777'],
  [/\b(kubectl|terraform)\s+(delete|destroy)\b/i, 'infra delete'],
]

/** The risky pattern a shell command matches, or ''. */
export const riskyReason = (command: string): string => RISKY.find(([re]) => re.test(command))?.[1] ?? ''

// ---------------------------------------------------------------------------
// Prompt cache
// ---------------------------------------------------------------------------
export type TokenUsage = {
  input_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

/** Share of input tokens served from cache, 0-100, or null with no input. */
export const cacheHitPct = (u: TokenUsage | undefined | null): number | null => {
  if (!u) return null
  const total = u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens
  return total > 0 ? Math.round((u.cache_read_input_tokens / total) * 100) : null
}

// ---------------------------------------------------------------------------
// Disk space
// ---------------------------------------------------------------------------
export type Disk = { name: string; freeBytes: number; totalBytes: number }

/** PowerShell `Get-PSDrive` lines: "<Name> <Free> <Used>". */
export const parseWindowsDisks = (out: string): Disk[] =>
  out
    .split(/\r?\n/)
    .map(l => l.trim().split(/\s+/))
    .filter(p => p.length === 3 && /^\d+$/.test(p[1]) && /^\d+$/.test(p[2]))
    .map(([name, free, used]) => ({ name: `${name}:`, freeBytes: Number(free), totalBytes: Number(free) + Number(used) }))
    .filter(d => d.totalBytes > 0)

/** `df -Pk` output: real filesystems only, by mount point. */
export const parseDf = (out: string): Disk[] =>
  out
    .split(/\r?\n/)
    .slice(1)
    .map(l => l.trim().split(/\s+/))
    .filter(p => p.length >= 6 && p[0].startsWith('/dev/') && /^\d+$/.test(p[1]))
    .map(p => ({ name: p.slice(5).join(' '), freeBytes: Number(p[3]) * 1024, totalBytes: Number(p[1]) * 1024 }))

export const LOW_DISK_PCT = 10
export const LOW_DISK_BYTES = 5 * 1024 ** 3
export const isDiskLow = (d: Disk) => d.freeBytes < LOW_DISK_BYTES || (d.freeBytes / d.totalBytes) * 100 < LOW_DISK_PCT

export const bytes = (n: number) => {
  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let i = 0
  let v = n
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024
    i += 1
  }
  return `${v >= 100 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`
}

/** A task counts as long, worth a ping when it ends, after this long running. */
export const LONG_TASK_MS = 5 * 60_000

// ---------------------------------------------------------------------------
// One-line session summaries (opt-in: one small model call per finished turn)
// ---------------------------------------------------------------------------
const squash = (s: string) => s.replace(/\s+/g, ' ').trim()
const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1)}…` : s)

export const SUMMARY_SYSTEM =
  'You write one-line status labels for a developer dashboard. Reply with the label only: no quotes, no markdown, no preamble.'

/** The prompt for the label. Inputs are clipped, so a call stays small (a few hundred tokens). */
export const summaryPrompt = (request: string, answer: string, steps: readonly string[]) =>
  [
    'A coding assistant session just finished a turn. In at most 12 words, present tense, say what the session is working on.',
    `Request: ${clip(squash(request), 300) || '(none)'}`,
    `Latest steps: ${steps.slice(-5).map(s => clip(squash(s), 60)).join('; ') || '(none)'}`,
    `Reply: ${clip(squash(answer), 500) || '(none)'}`,
  ].join('\n')

/** Cleans the model's reply into one short line; '' when nothing usable. */
export const tidySummary = (text: string, max = 80): string => {
  const line = (text.split(/\r?\n/).find(l => l.trim()) ?? '')
    .replace(/^[\s>*#\-"'`“‘]+/, '')
    .replace(/[\s"'`”’]+$/, '')
    .replace(/\*\*|__|`/g, '')
    .replace(/^(status|label|summary)\s*:\s*/i, '')
    .replace(/\.$/, '')
  const out = squash(line)

  return out.length > max ? `${out.slice(0, max - 1)}…` : out
}

files.hooks/exe.ts:
// dev-dash: finding and running `git` and `gh` when the process PATH may be stale. No session needed, so it tests
// with a stub for the process call and a stub clock.
//
// $.process.run rejects both when a program cannot be started and when it started but ran past its time limit
// (the child is killed and the call rejects). The API gives no wording for either, so the two are told apart by
// time: a program that cannot start fails almost at once, a timeout takes the whole allowance. A call that ran for
// (nearly) its whole timeoutMs was a timeout and is rethrown as it is; one that failed sooner is treated as "not
// there" and the next place is tried.

/** A call that ran for at least this much less than its allowance than the full timeoutMs still counts as a timeout. */
export const TIMEOUT_SLACK_MS = 250

/** True when a call that started at `startedAt` and failed at `endedAt` ran for (nearly) all of `timeoutMs`. */
export function ranToTimeout(startedAt: number, endedAt: number, timeoutMs: number): boolean {
  // The slack never takes more than half the allowance, so a very short timeout still means something.
  return endedAt - startedAt >= Math.max(timeoutMs / 2, timeoutMs - TIMEOUT_SLACK_MS)
}

export type RunExe<R> = {
  /** Starts `argv` (argv[0] the program) with the given time limit; rejects if it cannot start or runs out of time. */
  run: (argv: string[], timeoutMs: number) => Promise<R>
  /** The program as it is called by name: `git`, `gh`. */
  name: string
  args: string[]
  timeoutMs: number
  /** Where else to look, in order, asked only once the program by name could not be started. */
  fallbacks: () => Promise<string[]>
  /** What worked last time, by name; the caller keeps it between calls. */
  found: Map<string, string>
  now?: () => number
}

type Attempt<R> = { value: R } | { err: unknown; isTimeout: boolean }

/**
 * Runs the program: by the path that worked last time, else by name, else from each fallback in turn. A timeout is
 * rethrown at once from wherever it happened (a slow program is not retried elsewhere, and a remembered path that
 * timed out is kept); any other failure moves on to the next place. If nowhere works, the first failure is thrown.
 */
export async function runExe<R>(o: RunExe<R>): Promise<R> {
  const now = o.now ?? Date.now
  const attempt = async (exe: string): Promise<Attempt<R>> => {
    const started = now()
    try {
      return { value: await o.run([exe, ...o.args], o.timeoutMs) }
    } catch (err) {
      return { err, isTimeout: ranToTimeout(started, now(), o.timeoutMs) }
    }
  }

  const known = o.found.get(o.name)
  if (known) {
    const a = await attempt(known)
    if ('value' in a) return a.value
    if (a.isTimeout) throw a.err
    o.found.delete(o.name)
  }
  const first = await attempt(o.name)
  if ('value' in first) {
    o.found.set(o.name, o.name)

    return first.value
  }
  if (first.isTimeout) throw first.err
  for (const exe of await o.fallbacks()) {
    const a = await attempt(exe)
    if ('value' in a) {
      o.found.set(o.name, exe)

      return a.value
    }
    if (a.isTimeout) throw a.err
  }
  throw first.err
}

files.hooks/handoff.ts:
// dev-dash: the handoff note written when a session compacts. Pure functions only, so they test
// without a session; register.tsx collects the facts and writes the file.
//
// The note is for the person (or the next session) picking the work up after the conversation was
// squeezed down: where the session was, what it was doing, what it had touched, and the summary
// the compaction kept.

import type { PlanProgress } from '../types'

export const SUMMARY_MAX = 2000
export const FILES_MAX = 15

export type HandoffFacts = {
  at: number
  sessionId: string
  name: string
  repo: string
  branch: string
  cwd: string
  /** What compacted: the person's `/compact`, the engine at its threshold, a plugin. */
  trigger: string
  tokensBefore?: number
  tokensAfter?: number
  plan: PlanProgress | null
  lastTool: string
  /** Files edited in the last 30 minutes, as the heartbeat keeps them. */
  files: readonly string[]
  /** The summary the compaction kept: the text of its first message. */
  summary: string
}

const pad = (n: number) => String(n).padStart(2, '0')

/** `2026-10-03 16:42` in the machine's time. */
export const stampOf = (at: number) => {
  const d = new Date(at)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

/** A file name for the note: sortable by time, and safe on every filesystem. */
export const handoffName = (at: number, sessionId: string) => {
  const d = new Date(at)
  const day = `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`

  return `${day}-${sessionId.replace(/[^A-Za-z0-9-]/g, '').slice(0, 8) || 'session'}.md`
}

/** How many notes are kept in all; older ones are deleted when a new one is written. */
export const HANDOFFS_KEPT = 30

/** Exactly what `handoffName` makes, so nothing else in the folder is ever touched. */
const NOTE_NAME = /^\d{8}-\d{6}-[A-Za-z0-9-]{1,8}\.md$/

/** The notes to delete so that only the newest `keep` remain. The name starts with the time, so it sorts by age. */
export const staleNotes = (names: readonly string[], keep = HANDOFFS_KEPT): string[] =>
  names
    .filter(n => NOTE_NAME.test(n))
    .sort()
    .slice(0, Math.max(0, names.filter(n => NOTE_NAME.test(n)).length - keep))

const tokens = (n: number | undefined) => (n === undefined ? '' : n >= 1000 ? `${Math.round(n / 1000)}k` : String(n))

/** A cut that says it cut. */
export const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, Math.max(1, n - 1)).trimEnd()}…` : s)

export function handoffNote(f: HandoffFacts): string {
  const size = f.tokensBefore !== undefined && f.tokensAfter !== undefined ? ` (${tokens(f.tokensBefore)} -> ${tokens(f.tokensAfter)} tokens)` : ''
  const where = [f.repo, f.branch].filter(Boolean).join('@')
  const lines = [
    `# Handoff: ${f.name || where || f.sessionId}`,
    '',
    `Compacted ${stampOf(f.at)} (${f.trigger})${size}.`,
    where ? `Repo: ${where}${f.cwd ? ` · ${f.cwd}` : ''}` : f.cwd ? `Directory: ${f.cwd}` : '',
    `Resume: \`claude --resume ${f.sessionId}\``,
  ]
  if (f.plan) {
    lines.push('', `## Plan: ${f.plan.done}/${f.plan.total} done`, f.plan.done < f.plan.total && f.plan.current ? `In progress: ${f.plan.current}` : '')
  }
  if (f.lastTool) lines.push('', `Last step: ${f.lastTool}`)
  if (f.files.length > 0) {
    const shown = f.files.slice(0, FILES_MAX)
    lines.push('', '## Files touched recently', ...shown.map(p => `- ${p}`))
    if (f.files.length > shown.length) lines.push(`- … and ${f.files.length - shown.length} more`)
  }
  const summary = f.summary.trim()
  lines.push('', '## What the compaction kept', summary ? clip(summary, SUMMARY_MAX) : '(no summary text)')

  return `${lines.filter((l, i, all) => !(l === '' && all[i - 1] === '') && l !== undefined).join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`
}

files.hooks/entertainment.ts:
// dev-dash: the Entertainment tab's data. Pure functions only, so they test without a session.
//
// "Now playing" is an opt-in (off until the person turns it on). It reads what the Spotify app on THIS machine
// reports, with a local command and no network and no login: the media information Windows shows on its volume
// overlay, AppleScript on macOS, playerctl on Linux. Nothing is sent anywhere or written to disk.

import type { NowPlaying, TabId } from '../types'

export const TABS: ReadonlyArray<{ id: TabId; label: string }> = [
  { id: 'dashboard', label: 'Dashboard' },
  { id: 'entertainment', label: 'Entertainment' },
  { id: 'custom', label: 'Custom' },
]

export const isTab = (v: unknown): v is TabId => TABS.some(t => t.id === v)

export type Platform = 'windows' | 'mac' | 'linux'

// Windows keeps a "media session" for each app that plays media (the info behind the volume overlay): the app, the
// track and whether it is playing or paused. Unlike the app's window title it keeps the track while paused. It is
// there once Spotify has started a song. No session means Spotify is either open with nothing started, or closed.
const WINDOWS_SCRIPT = [
  "$ErrorActionPreference='Stop'",
  'try {',
  '  Add-Type -AssemblyName System.Runtime.WindowsRuntime',
  "  $a=([System.WindowsRuntimeSystemExtensions].GetMethods()|Where-Object{$_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1'})[0]",
  '  function W($o,$t){$k=$a.MakeGenericMethod($t).Invoke($null,@($o));$k.Wait(-1)|Out-Null;$k.Result}',
  '  [void][Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager,Windows.Media.Control,ContentType=WindowsRuntime]',
  '  $m=W ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager]::RequestAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager])',
  "  foreach($s in $m.GetSessions()){ if($s.SourceAppUserModelId -match 'Spotify'){",
  '    $p=W ($s.TryGetMediaPropertiesAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionMediaProperties])',
  "    Write-Output ($s.GetPlaybackInfo().PlaybackStatus.ToString()+'|'+$p.Artist+' - '+$p.Title); return } }",
  '} catch {}',
  "if(Get-Process -Name Spotify -ErrorAction SilentlyContinue){'OPEN'}else{'CLOSED'}",
].join('\n')

/** The command (as separate arguments, no shell) that prints what Spotify is playing on this platform. */
export const nowPlayingCommand = (platform: Platform): string[] => {
  if (platform === 'windows') return ['powershell', '-NoProfile', '-Command', WINDOWS_SCRIPT]
  if (platform === 'mac') {
    return [
      'osascript',
      '-e', 'if application "Spotify" is not running then return "NOT_RUNNING"',
      '-e', 'tell application "Spotify"',
      '-e', 'if player state is playing then return "Playing|" & (artist of current track) & " - " & (name of current track)',
      '-e', 'if player state is paused then return "Paused|" & (artist of current track) & " - " & (name of current track)',
      '-e', 'return ""',
      '-e', 'end tell',
    ]
  }

  return ['playerctl', '-p', 'spotify', 'metadata', '--format', '{{status}}|{{artist}} - {{title}}']
}

const clean = (s: string) => s.replace(/\s+/g, ' ').trim()

/** `Playing|Artist - Title`, `Paused|...`, or a status with no track: Windows, macOS and Linux all print this shape. */
function statusLine(out: string, at: number): NowPlaying | null {
  const m = /^(Playing|Paused|Stopped|Changing|Opened|Closed)\|(.*)$/i.exec(out)
  if (!m) return null
  const status = m[1].toLowerCase()
  const track = clean(m[2])
  if (!track || track === '-') return { state: 'idle', track: '', at }
  if (status === 'playing') return { state: 'playing', track, at }
  if (status === 'paused') return { state: 'paused', track, at }

  return { state: 'idle', track: '', at }
}

/**
 * What the command printed, as a reading. `exitCode` matters on Linux, where no player is a non-zero exit.
 * Windows prints a status line, or OPEN (Spotify running, nothing started) or CLOSED (not running).
 */
export function parseNowPlaying(platform: Platform, stdout: string, exitCode: number, at: number): NowPlaying {
  const out = clean(stdout)
  if (platform === 'windows') {
    if (out === 'CLOSED') return { state: 'closed', track: '', at }
    if (out === 'OPEN') return { state: 'idle', track: '', at }

    return statusLine(out, at) ?? { state: 'unavailable', track: '', at }
  }
  if (platform === 'mac') {
    if (out === 'NOT_RUNNING') return { state: 'closed', track: '', at }
    if (!out) return { state: 'idle', track: '', at }

    return statusLine(out, at) ?? { state: 'unavailable', track: '', at }
  }
  if (exitCode !== 0 || !out) return { state: 'closed', track: '', at }

  return statusLine(out, at) ?? { state: 'unavailable', track: '', at }
}

/** The command could not run at all (the tool is missing): shown as "unavailable", not as "closed". */
export const unavailable = (at: number): NowPlaying => ({ state: 'unavailable', track: '', at })

files.hooks/keys.ts:
// dev-dash: row ids, the actions a row offers, and snooze/dismiss. Pure functions only, so they test without a session.
//
// The pane is driven with the generic keys the engine already gives a focused pane: Tab and the arrow keys move
// the focus ring over the Buttons, Enter presses the one in the ring, Esc gives the keyboard back to the prompt and
// ctrl+x tab takes it back. Every row has a small marker Button as its stop in the ring, and pressing it opens the
// row's actions (copy, snooze, dismiss). No letter hotkeys.

import type { AgentRow, DiskRow, LimitRow, PrRow, SessionRow } from '../types'
import type { DashSection } from '../types'

// ---------------------------------------------------------------------------
// The keys, as the help panel explains them
// ---------------------------------------------------------------------------
export const HELP_KEYS: ReadonlyArray<readonly [string, string]> = [
  ['↑ ↓  or  Tab', 'move the highlight to the previous or next row or button'],
  ['Enter', 'press the highlighted button; on a row, open its actions'],
  ['Esc', 'give the keyboard back to the prompt'],
  ['ctrl+x tab', 'bring the keyboard back to this pane (or type /dash)'],
  ['1 – 9', 'fold or unfold a section (Dashboard tab)'],
  ['tab buttons', 'at the top: Dashboard, Entertainment, Custom. Move onto one and press Enter'],
]

export const SNOOZE_MS = 15 * 60_000

// ---------------------------------------------------------------------------
// Row ids. Each is stable while the thing it names is the same thing, and changes when it is a new
// episode (a session that waits again, a new stuck reason), so a dismissal does not hide the next one.
// ---------------------------------------------------------------------------
export const ids = {
  wait: (r: SessionRow) => `wait:${r.id}:${r.stateSince}`,
  stuck: (r: SessionRow) => `stuck:${r.id}:${r.stuck}`,
  risky: (r: SessionRow) => `risky:${r.id}:${r.risky}`,
  disk: (d: DiskRow) => `disk:${d.name}`,
  clash: (file: string) => `clash:${file}`,
  limit: (l: LimitRow) => `limit:${l.kind}`,
  ci: (p: PrRow) => `ci:${p.repo}#${p.number}`,
  review: (p: PrRow) => `review:${p.repo}#${p.number}`,
  session: (r: SessionRow) => `s:${r.id}`,
  agent: (a: AgentRow) => `a:${a.id}`,
  pr: (p: PrRow) => `pr:${p.repo}#${p.number}`,
  rv: (p: PrRow) => `rv:${p.repo}#${p.number}`,
}

export const resumeCommand = (sessionId: string) => `claude --resume ${sessionId}`

// ---------------------------------------------------------------------------
// Snooze and dismiss
// ---------------------------------------------------------------------------
export type Muting = { snoozed: Record<string, number>; dismissed: readonly string[]; now: number }

export const noMuting = (now: number): Muting => ({ snoozed: {}, dismissed: [], now })

export const isMuted = (m: Muting, id: string) => m.dismissed.includes(id) || (m.snoozed[id] ?? 0) > m.now

/** `snoozed` with `id` added and expired entries dropped. */
export const snoozeAdd = (snoozed: Record<string, number>, id: string, now: number): Record<string, number> => {
  const out: Record<string, number> = {}
  for (const [k, until] of Object.entries(snoozed)) if (until > now) out[k] = until
  out[id] = now + SNOOZE_MS

  return out
}

export const dismissAdd = (dismissed: readonly string[], id: string, keep = 200): string[] =>
  dismissed.includes(id) ? [...dismissed] : [...dismissed, id].slice(-keep)

// ---------------------------------------------------------------------------
// The rows that can be opened, in the order the pane draws them
// ---------------------------------------------------------------------------
export type Item = {
  id: string
  kind: 'attention' | 'session' | 'agent' | 'pr' | 'review'
  /** What Copy puts on the clipboard. */
  copy: string
  /** What the copy button is called, and what the toast says was copied. */
  what: string
  /** True for Attention items, the only ones that can be snoozed or dismissed. */
  canMute: boolean
}

export const itemById = (items: readonly Item[], id: string | null | undefined) => items.find(i => i.id === id)

export type RowAction = { id: 'copy' | 'snooze' | 'dismiss'; label: string }

/** The buttons a row shows when it is opened. Only Attention items can be muted. */
export const actionsFor = (item: Item): RowAction[] => [
  { id: 'copy', label: `copy ${item.what}` },
  ...(item.canMute ? ([{ id: 'snooze', label: 'snooze 15m' }, { id: 'dismiss', label: 'dismiss' }] as const) : []),
]

/** Which of the sections that have rows are folded away: their rows are not shown. */
export const isShown = (folded: readonly DashSection[], id: DashSection) => !folded.includes(id)

/** How many rows the pane draws per section. */
export type Caps = { reviews: number; sessions: number; agents: number }

files.hooks/icons.ts:
// dev-dash: the icons for where a watch lives. Pure data, so it tests without a session.
//
// The official GitHub mark is not a Unicode character, so a terminal can only show it from the font it is set to.
// Nerd Fonts carry it, but in most terminals it shows as an empty box, so the default is the emoji style, which
// every font has; `/dash-icons nerd` opts in to the official mark and `ascii` falls back to plain letters. The
// style is the person's choice and is remembered. A source gets its own entry here when there are watches for it.

import type { IconStyle, WatchKind } from '../types'

export type Source = 'github'

export const ICON_STYLES: readonly IconStyle[] = ['emoji', 'nerd', 'ascii']
export const DEFAULT_ICON_STYLE: IconStyle = 'emoji'

/** Nerd Fonts: Font Awesome `nf-fa-github` (U+F09B). */
export const ICONS: Record<Source, Record<IconStyle, string>> = {
  github: { emoji: '🐙', nerd: '', ascii: 'GH' },
}

export const sourceOf = (_kind: WatchKind): Source => 'github'

export const iconFor = (source: Source, style: IconStyle | undefined): string => ICONS[source][style ?? DEFAULT_ICON_STYLE]

/** `nerd`, `emoji` or `ascii` (any case), else null. */
export const parseIconStyle = (s: string): IconStyle | null => {
  const t = s.trim().toLowerCase()

  return (ICON_STYLES as readonly string[]).includes(t) ? (t as IconStyle) : null
}

files.hooks/progress.ts:
// dev-dash: per-session progress data (plan progress, sources fetched, files changed this turn).
// Pure functions only, so they test without a session. register.tsx collects, progress-view.tsx draws.

import type { ChangedFile, PlanProgress, SourceRow } from '../types'

export const SOURCES_KEPT = 20
export const TURN_FILES_KEPT = 12

const text = (v: unknown) => (typeof v === 'string' ? v.trim() : '')

/** Progress of the list a session keeps with TodoWrite; null when the input has no todos. */
export function planOf(input: Record<string, unknown>): PlanProgress | null {
  const todos = input.todos
  if (!Array.isArray(todos) || todos.length === 0) return null
  const items = todos.map(t => (t && typeof t === 'object' ? (t as Record<string, unknown>) : {}))
  const done = items.filter(t => t.status === 'completed').length
  const active = items.find(t => t.status === 'in_progress') ?? items.find(t => t.status === 'pending')
  const current = active ? text(active.activeForm) || text(active.content) : ''

  return { done, total: items.length, current }
}

export const QUERY_MAX = 80

/**
 * What is safe to keep of a fetched URL: scheme, host and path. Userinfo (`user:pass@`),
 * query and fragment can hold tokens or keys, and the label is written to disk, so they never get in.
 */
export function stripUrl(url: string): string {
  const m = /^([a-z][a-z0-9+.-]*):\/\/([^/?#]*)([^?#]*)/i.exec(url)
  if (!m) return url.split(/[?#]/)[0].replace(/\/\/[^/@\s]*@/, '//')
  const host = m[2].slice(m[2].lastIndexOf('@') + 1)

  return `${m[1].toLowerCase()}://${host}${m[3]}`
}

/** A URL a session fetched or a query it searched, from one tool call; null for any other tool. */
export function sourceOf(tool: string, input: Record<string, unknown>, at: number): SourceRow | null {
  if (tool === 'WebFetch' && text(input.url)) return { at, kind: 'fetch', label: stripUrl(text(input.url)) }
  if (tool === 'WebSearch' && text(input.query)) {
    const q = text(input.query)
    return { at, kind: 'search', label: q.length > QUERY_MAX ? `${q.slice(0, QUERY_MAX - 1)}…` : q }
  }

  return null
}

/** Newest first, one entry per source (a repeat moves to the front), capped. */
export function addSource(list: readonly SourceRow[], next: SourceRow, keep = SOURCES_KEPT): SourceRow[] {
  const rest = list.filter(s => !(s.kind === next.kind && s.label === next.label))

  return [next, ...rest].slice(0, keep)
}

/** `https://example.com/a/b?x=1` -> `example.com/a/b`; anything else comes back as it was. */
export function shortUrl(url: string): string {
  const m = /^[a-z][a-z0-9+.-]*:\/\/([^/?#]+)([^?#]*)/i.exec(url)
  if (!m) return url
  const path = m[2].replace(/\/+$/, '')

  return `${m[1].replace(/^www\./, '')}${path}`
}

/** Output of `git diff --numstat`: `added<TAB>removed<TAB>path`, with `-` for binary files. */
export function parseNumstat(out: string): ChangedFile[] {
  const files: ChangedFile[] = []
  for (const line of out.split(/\r?\n/)) {
    const m = /^(\d+|-)\t(\d+|-)\t(.+)$/.exec(line)
    if (m) files.push({ path: m[3], added: m[1] === '-' ? 0 : Number(m[1]), removed: m[2] === '-' ? 0 : Number(m[2]) })
  }

  return files
}

/** Lines in a file's text, for a new file git has no diff for yet. */
export const countLines = (s: string) => (s === '' ? 0 : s.split(/\r?\n/).length - (s.endsWith('\n') ? 1 : 0))

export const totals = (files: readonly ChangedFile[]) => ({
  added: files.reduce((n, f) => n + f.added, 0),
  removed: files.reduce((n, f) => n + f.removed, 0),
})

/** A plan counts as live while it is unfinished, or for a while after it finished. */
export const PLAN_LINGER_MS = 10 * 60_000
export const isPlanLive = (p: PlanProgress | null | undefined, now: number, updatedAt: number) =>
  !!p && (p.done < p.total || now - updatedAt < PLAN_LINGER_MS)

