// dev-dash: what needs the person, and which rows the cursor can land on. Pure, so it tests without a
// session. The pane, the band above the prompt and the toasts all draw from attentionOf, so a snooze or a
// dismissal reaches all three.

import type { DashSection, LimitRow, Snapshot } from '../types'
import { type Caps, type Item, type Muting, ids, isMuted, isShown, resumeCommand } from './keys'
import { bytes, collisionsOf, isDiskLow } from './monitor'

/** True when the limit will run out before it resets, at the recent pace. */
export const isLimitAtRisk = (l: LimitRow, now: number) =>
  l.etaMs !== null && (l.resetsAt === null || now + l.etaMs < l.resetsAt)

/** What the Attention section counts, in urgency order, less anything snoozed or dismissed. */
export const attentionOf = (s: Snapshot, m: Muting) => {
  const keep = <T,>(list: readonly T[], id: (t: T) => string) => list.filter(t => !isMuted(m, id(t)))
  const all = {
    waiting: s.sessions.filter(r => r.state === 'waiting'),
    stuck: s.sessions.filter(r => r.stuck),
    risky: s.sessions.filter(r => r.risky),
    disks: (s.disks ?? []).filter(isDiskLow),
    collisions: collisionsOf(s.sessions),
    limits: (s.limits ?? []).filter(l => l.pct >= 90 || isLimitAtRisk(l, m.now)),
    failing: (s.prs?.mine ?? []).filter(p => p.ci === 'failing' || p.conflicts),
    reviews: s.prs?.toReview ?? [],
  }
  const waiting = keep(all.waiting, ids.wait)
  const stuck = keep(all.stuck, ids.stuck)
  const risky = keep(all.risky, ids.risky)
  const disks = keep(all.disks, ids.disk)
  const collisions = keep(all.collisions, c => ids.clash(c.file))
  const limits = keep(all.limits, ids.limit)
  const failing = keep(all.failing, ids.ci)
  const reviews = keep(all.reviews, ids.review)
  const urgent = waiting.length + stuck.length + risky.length + collisions.length + limits.length + disks.length + failing.length
  const total = urgent + reviews.length
  const before = Object.values(all).reduce((n, list) => n + list.length, 0)

  return { waiting, stuck, risky, collisions, limits, disks, failing, reviews, urgent, total, hidden: before - total }
}

export type Attention = ReturnType<typeof attentionOf>

/** The rows the cursor can land on, in the order the pane draws them. A folded section has none. */
export const itemsOf = (s: Snapshot, att: Attention, folded: readonly DashSection[], caps: Caps): Item[] => {
  const out: Item[] = []
  const resume = (sessionId: string) => resumeCommand(sessionId)

  if (isShown(folded, 'attention')) {
    for (const r of att.waiting) out.push({ id: ids.wait(r), kind: 'attention', copy: resume(r.id), what: 'resume command', canMute: true })
    for (const r of att.stuck) out.push({ id: ids.stuck(r), kind: 'attention', copy: resume(r.id), what: 'resume command', canMute: true })
    for (const r of att.risky) out.push({ id: ids.risky(r), kind: 'attention', copy: resume(r.id), what: 'resume command', canMute: true })
    for (const d of att.disks) out.push({ id: ids.disk(d), kind: 'attention', copy: `disk ${d.name} low: ${bytes(d.freeBytes)} free of ${bytes(d.totalBytes)}`, what: 'disk summary', canMute: true })
    for (const c of att.collisions) out.push({ id: ids.clash(c.file), kind: 'attention', copy: c.file, what: 'file path', canMute: true })
    for (const l of att.limits) out.push({ id: ids.limit(l), kind: 'attention', copy: `${l.kind} limit ${Math.round(l.pct)}%`, what: 'limit summary', canMute: true })
    for (const p of att.failing) out.push({ id: ids.ci(p), kind: 'attention', copy: p.url || `#${p.number}`, what: 'PR link', canMute: true })
    for (const p of att.reviews.slice(0, caps.reviews)) out.push({ id: ids.review(p), kind: 'attention', copy: p.url || `#${p.number}`, what: 'PR link', canMute: true })
  }
  if (isShown(folded, 'sessions')) {
    for (const r of s.sessions.slice(0, caps.sessions)) out.push({ id: ids.session(r), kind: 'session', copy: resume(r.id), what: 'resume command', canMute: false })
  }
  if (isShown(folded, 'agents')) {
    for (const a of (s.agents ?? []).slice(0, caps.agents)) out.push({ id: ids.agent(a), kind: 'agent', copy: resume(a.sessionId), what: 'resume command for its session', canMute: false })
  }
  if (isShown(folded, 'prs') && s.prs && !s.prs.error) {
    for (const p of s.prs.mine) out.push({ id: ids.pr(p), kind: 'pr', copy: p.url || `#${p.number}`, what: 'PR link', canMute: false })
    for (const p of s.prs.toReview) out.push({ id: ids.rv(p), kind: 'review', copy: p.url || `#${p.number}`, what: 'PR link', canMute: false })
  }

  return out
}

files.hooks/beat.ts:
// dev-dash: "claude beat", the header's activity trace: a line graph of how much effort Claude was putting in, one
// column per sync, newest at the right. Pure functions only, so they test without a session.
//
// "Effort" is a score made at each sync from what was going on (see effortOf): running sessions count most, then
// busy agents, then waiting sessions, plus how many tool calls this session made since the last sync. The line is
// drawn with solid line characters, so it is one connected stroke and not a scatter of dots: `─` along a level
// stretch, `│` for the steep sides, and `╭ ╮ ╰ ╯` where it turns. Nothing running is a flat line along the bottom.

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

/**
 * How much effort one sync saw. A running session is 3, a busy agent 2, a session waiting on someone 1, and each
 * tool call this session made since the last sync 0.6 (at most 12 of them, so a burst cannot flatten everything else).
 */
export function effortOf(running: number, waiting: number, workingAgents: number, toolCalls: number): number {
  const n = (v: number) => (Number.isFinite(v) ? Math.max(0, v) : 0)

  return n(running) * 3 + n(waiting) * 1 + n(workingAgents) * 2 + Math.min(n(toolCalls), 12) * 0.6
}

/** The smallest top of the scale, so a little effort looks like a little and not like the most there has ever been. */
export const MIN_SCALE = 6

/**
 * The last `cells` efforts as a level per column (0 = bottom row, `rows - 1` = top), newest at the right. Fewer
 * syncs than fit are placed at the right with zero effort to their left. The top of the scale is the busiest sync in
 * view, but never less than MIN_SCALE.
 */
export function scaleLevels(activity: readonly number[], cells: number, rows: number): number[] {
  const width = Math.max(1, Math.floor(cells))
  const top = Math.max(1, Math.floor(rows)) - 1
  const window = activity.slice(-width).map(v => (Number.isFinite(v) ? Math.max(0, v) : 0))
  const values = [...Array<number>(width - window.length).fill(0), ...window]
  const max = Math.max(MIN_SCALE, ...values)

  return values.map(v => clamp(Math.round((v / max) * top), 0, top))
}

/**
 * Levels (0 = bottom, one per column) drawn as `rows` rows of text, top row first. Where the level changes between
 * two columns the line turns in the new column: up is `╯` where it leaves the old level, `│` through the levels
 * between and `╭` where it arrives; down is `╮`, `│` and `╰`. The same level is `─`.
 */
export function drawLine(columns: readonly number[], rows: number): string[] {
  const height = Math.max(1, Math.floor(rows))
  const grid: string[][] = Array.from({ length: height }, () => Array<string>(columns.length).fill(' '))
  const put = (level: number, x: number, ch: string) => {
    grid[height - 1 - level][x] = ch
  }
  let prev = -1
  columns.forEach((raw, x) => {
    const y = clamp(Math.round(raw), 0, height - 1)
    if (prev < 0 || y === prev) {
      put(y, x, '─')
    } else if (y > prev) {
      put(prev, x, '╯')
      for (let level = prev + 1; level < y; level++) put(level, x, '│')
      put(y, x, '╭')
    } else {
      put(prev, x, '╮')
      for (let level = y + 1; level < prev; level++) put(level, x, '│')
      put(y, x, '╰')
    }
    prev = y
  })

  return grid.map(row => row.join(''))
}

/** The header's "claude beat": the effort history as a connected line graph, `cells` columns wide and `rows` rows tall. */
export function claudeBeat(activity: readonly number[], cells: number, rows = 5): string[] {
  const width = Math.max(1, Math.floor(cells))
  const height = Math.max(1, Math.floor(rows))

  return drawLine(scaleLevels(activity, width, height), height)
}

/**
 * One agent's swimlane on a time axis shared by every agent: `·` before it started, `▬` while it ran, `·` after.
 * `from`..`to` is the window; the agent ran `startedAt`..`endAt`.
 */
export const lane = (startedAt: number, endAt: number, from: number, to: number, cells: number) => {
  const n = Math.max(1, Math.floor(cells))
  const span = Math.max(1, to - from)
  const at = (t: number) => Math.min(n, Math.max(0, ((t - from) / span) * n))
  const a = Math.min(n - 1, Math.floor(at(startedAt)))
  const b = Math.min(n, Math.max(a + 1, Math.ceil(at(endAt))))

  return '·'.repeat(a) + '▬'.repeat(b - a) + '·'.repeat(n - b)
}

/** Which row (0 = top) of the drawn beat holds its newest sample: the one place the tip blinks. */
export const tipRow = (activity: readonly number[], cells: number, rows: number): number => {
  const height = Math.max(1, Math.floor(rows))
  const levels = scaleLevels(activity, Math.max(1, Math.floor(cells)), height)

  return height - 1 - (levels[levels.length - 1] ?? 0)
}

files.hooks/progress-view.tsx:
// dev-dash: the Plan, Sources and Files sections. Each is drawn from the sessions' heartbeats,
// and kept out of render.tsx so changes to the pane and to these sections merge cleanly.
//
// render.tsx passes in what it already has (its Heading, Box and Text, widths, the fold list),
// so there is nothing here to keep in step with the rest of the pane.

import type { ChangedFile, DashSection, SessionRow, SourceRow } from '../types'
import { isPlanLive, shortUrl, totals } from './progress'

// The Box, Text and Heading render.tsx resolved for this render.
// biome-ignore lint/suspicious/noExplicitAny: element components come from `$.ui.resolve(e)`
type El = (props: any) => any

export type ProgressView = {
  Box: El
  Text: El
  Heading: (p: { id: DashSection; hotkey: string; title: string; tone?: string; summary: string }) => unknown
  folded: readonly DashSection[]
  sessions: readonly SessionRow[]
  selfId: string
  W: number
  isNarrow: boolean
  now: number
  tone: { ok: string; warn: string; bad: string; info: string }
  fmt: {
    ago: (ms: number) => string
    cut: (s: string, n: number) => string
    bar: (pct: number, cells: number) => string
  }
}

const label = (r: SessionRow) => r.name || (r.branch ? `${r.repo}@${r.branch}` : r.repo)
const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`
const baseName = (p: string) => p.replace(/[\\/]+$/, '').split(/[\\/]/).pop() ?? p

export function progressSections(v: ProgressView) {
  const { Box, Text, Heading, folded, W, isNarrow, now, tone, fmt } = v
  const live = v.sessions.filter(r => r.hasPlugin)

  // ---- Plan: one line per session that keeps a todo list -------------------------
  const planned = live.filter(r => isPlanLive(r.plan, now, r.planAt ?? 0))
  const doneCount = planned.filter(r => r.plan && r.plan.done >= r.plan.total).length
  const plan = (
    <Box flexDirection="column">
      <Heading
        id="plan"
        hotkey="7"
        title={`Plan (${planned.length})`}
        summary={planned.length ? `${planned.length - doneCount} in progress · ${doneCount} done` : 'no plans'}
      />
      {!folded.includes('plan') && (
        <Box flexDirection="column" paddingLeft={2}>
          {planned.length === 0 && <Text dimColor>No session has a todo list right now.</Text>}
          {planned.map(r => {
            const p = r.plan as NonNullable<SessionRow['plan']>
            const isDone = p.done >= p.total
            const cells = isNarrow ? 5 : 10
            return (
              <Box flexDirection="column">
                <Box flexDirection="row">
                  <Text color={isDone ? tone.ok : tone.info}>{fmt.bar((p.done / p.total) * 100, cells)} </Text>
                  <Text bold={r.id === v.selfId}>
                    {p.done}/{p.total}
                  </Text>
                  <Text dimColor wrap="truncate-end"> · {fmt.cut(label(r), W - cells - 12)}</Text>
                </Box>
                {!isDone && p.current && (
                  <Box paddingLeft={2}>
                    <Text dimColor wrap="truncate-end">↳ {fmt.cut(p.current, W - 8)}</Text>
                  </Box>
                )}
              </Box>
            )
          })}
        </Box>
      )}
    </Box>
  )

  // ---- Sources: what sessions looked up, newest first ----------------------------
  const sources: Array<SourceRow & { who: string }> = live
    .flatMap(r => (r.sources ?? []).map(s => ({ ...s, who: label(r) })))
    .sort((a, b) => b.at - a.at)
  const shown = sources.slice(0, isNarrow ? 5 : 8)
  const sources_ = (
    <Box flexDirection="column">
      <Heading
        id="sources"
        hotkey="8"
        title={`Sources (${sources.length})`}
        summary={sources.length ? `${sources.filter(s => s.kind === 'fetch').length} fetched · ${sources.filter(s => s.kind === 'search').length} searched` : 'none yet'}
      />
      {!folded.includes('sources') && (
        <Box flexDirection="column" paddingLeft={2}>
          {sources.length === 0 && (
            <Text dimColor wrap="truncate-end">Nothing yet: fills when a session running dev-dash uses WebFetch or WebSearch.</Text>
          )}
          {shown.map(s => (
            <Text wrap="truncate-end">
              <Text color={s.kind === 'fetch' ? tone.info : tone.ok}>{s.kind === 'fetch' ? '↓' : '⌕'} </Text>
              {fmt.cut(s.kind === 'fetch' ? shortUrl(s.label) : s.label, W - 14 - (isNarrow ? 0 : fmt.cut(s.who, 14).length))}
              <Text dimColor> · {fmt.ago(now - s.at)}{isNarrow ? '' : ` · ${fmt.cut(s.who, 14)}`}</Text>
            </Text>
          ))}
          {sources.length > shown.length && <Text dimColor>+{sources.length - shown.length} more</Text>}
        </Box>
      )}
    </Box>
  )

  // ---- Files: what each session changed this turn --------------------------------
  const changed = live.filter(r => (r.turnFiles ?? []).length > 0)
  const all: ChangedFile[] = changed.flatMap(r => r.turnFiles ?? [])
  // A file git could not count (`counted: false`) is listed as edited, without made-up +/- numbers.
  const isCounted = (f: ChangedFile) => f.counted !== false
  const sum = totals(all.filter(isCounted))
  const files = (
    <Box flexDirection="column">
      <Heading
        id="files"
        hotkey="9"
        title={`Files (${all.length})`}
        summary={all.length ? `${plural(all.length, 'file')}${all.some(isCounted) ? ` · +${sum.added} -${sum.removed}` : ''}` : 'no edits this turn'}
      />
      {!folded.includes('files') && (
        <Box flexDirection="column" paddingLeft={2}>
          {changed.length === 0 && (
            <Text dimColor wrap="truncate-end">No session running dev-dash has edited a file in its current turn.</Text>
          )}
          {changed.map(r => {
            const t = totals((r.turnFiles ?? []).filter(isCounted))
            const rows = (r.turnFiles ?? []).slice(0, isNarrow ? 3 : 5)
            return (
              <Box flexDirection="column">
                <Box flexDirection="row">
                  <Text bold={r.id === v.selfId} wrap="truncate-end">{fmt.cut(label(r), W - 22)}</Text>
                  <Text dimColor> · {plural((r.turnFiles ?? []).length, 'file')} </Text>
                  {(r.turnFiles ?? []).some(isCounted) && <Text color={tone.ok}>+{t.added}</Text>}
                  {(r.turnFiles ?? []).some(isCounted) && <Text color={tone.bad}> -{t.removed}</Text>}
                </Box>
                {rows.map(f => (
                  <Box paddingLeft={2} flexDirection="row">
                    <Text wrap="truncate-end">{fmt.cut(baseName(f.path), W - 18)}</Text>
                    {isCounted(f) ? (
                      <Text color={tone.ok}> +{f.added}</Text>
                    ) : (
                      <Text dimColor> edited</Text>
                    )}
                    {isCounted(f) && <Text color={tone.bad}> -{f.removed}</Text>}
                  </Box>
                ))}
                {(r.turnFiles ?? []).length > rows.length && (
                  <Box paddingLeft={2}>
                    <Text dimColor>+{(r.turnFiles ?? []).length - rows.length} more</Text>
                  </Box>
                )}
              </Box>
            )
          })}
        </Box>
      )}
    </Box>
  )

  return { plan, sources: sources_, files }
}

files.hooks/tabs-view.tsx:
// dev-dash: the Entertainment and Custom tabs. Drawn from what render.tsx passes in, and kept out of render.tsx so
// the two tabs and the Dashboard tab can change without touching each other. Add a widget by adding a card here.

import type { NowPlaying } from '../types'

// The Box, Text and Button render.tsx resolved for this render.
// biome-ignore lint/suspicious/noExplicitAny: element components come from `$.ui.resolve(e)`
type El = (props: any) => any

export type TabView = {
  Box: El
  Text: El
  Button: El
  W: number
  now: number
  /** The card border the theme draws with. */
  border?: string
  tone: { ok: string; warn: string; bad: string; info: string; accent: string; mute: string }
  fmt: { ago: (ms: number) => string; cut: (s: string, n: number) => string }
}

/** A titled, bordered card: the shape every widget on the Entertainment tab shares. */
function Card(v: TabView, p: { title: string; tone?: string; children?: unknown }) {
  const { Box, Text, W, tone } = v

  return (
    <Box borderStyle={(v.border ?? 'round') as 'round'} borderColor={p.tone ?? tone.mute} paddingX={1} flexDirection="column" width={W}>
      <Text bold color={p.tone}>{p.title}</Text>
      {p.children}
    </Box>
  )
}

function nowPlayingCard(v: TabView, np: NowPlaying | null, isOn: boolean) {
  const { Box, Text, Button, tone, fmt, W, now } = v
  // Off by default: nothing is read until the person turns it on, with this button or /dash-spotify on.
  if (!isOn) {
    return Card(v, {
      title: '♪ Now playing · Spotify',
      children: (
        <Box flexDirection="column">
          <Text dimColor wrap="wrap">Off. Nothing is read until you turn it on. When on, this shows the track the Spotify app on this machine is playing: no login, no network.</Text>
          <Box flexDirection="row" marginTop={1}>
            <Button key="spotify-toggle" variant="primary" label="turn on" onPress={() => undefined} />
          </Box>
        </Box>
      ),
    })
  }
  const body =
    np === null ? (
      <Text dimColor>Looking for Spotify…</Text>
    ) : np.state === 'playing' ? (
      <Text color={tone.ok} bold wrap="truncate-end">▶ {fmt.cut(np.track, W - 8)}</Text>
    ) : np.state === 'paused' ? (
      <Text wrap="truncate-end">⏸ {fmt.cut(np.track, W - 16)} <Text dimColor>(paused)</Text></Text>
    ) : np.state === 'idle' ? (
      <Text dimColor wrap="wrap">Spotify is open, but no song has been started. Play one and it appears here.</Text>
    ) : np.state === 'closed' ? (
      <Text dimColor>Spotify is not running.</Text>
    ) : (
      <Text color={tone.warn} wrap="wrap">Could not read Spotify here. On Linux this needs `playerctl`.</Text>
    )

  return Card(v, {
    title: '♪ Now playing · Spotify',
    tone: np?.state === 'playing' ? tone.ok : undefined,
    children: (
      <Box flexDirection="column">
        {body}
        {np && (np.state === 'playing' || np.state === 'paused') && (
          <Text dimColor>read {fmt.ago(now - np.at)} ago from the Spotify app on this machine</Text>
        )}
        <Box flexDirection="row" marginTop={1}>
          <Button key="spotify-toggle" label="turn off" dimColor onPress={() => undefined} />
        </Box>
      </Box>
    ),
  })
}

function stocksCard(v: TabView) {
  const { Box, Text } = v

  return Card(v, {
    title: '▲ Stocks',
    children: (
      <Box flexDirection="column">
        <Text dimColor wrap="wrap">Not set up. Prices need a data source, and dev-dash makes no network calls beyond git and gh (CONTRIBUTING.md), so nothing is fetched.</Text>
        <Text dimColor wrap="wrap">The project owner has to approve a source before a watchlist can go here.</Text>
      </Box>
    ),
  })
}

/** The Entertainment tab: a column of cards. */
export function entertainmentView(v: TabView, np: NowPlaying | null, isSpotifyOn: boolean) {
  const { Box, Text } = v

  return (
    <Box flexDirection="column" marginTop={1} rowGap={1}>
      {nowPlayingCard(v, np, isSpotifyOn)}
      {stocksCard(v)}
      <Text dimColor>More widgets will land here. Spotify, when on, is read only while this tab is showing.</Text>
    </Box>
  )
}

/** The Custom tab: empty on purpose for now. */
export function customView(v: TabView) {
  const { Box, Text } = v

  return (
    <Box flexDirection="column" marginTop={1}>
      {Card(v, {
        title: 'Custom',
        children: (
          <Box flexDirection="column">
            <Text dimColor>Nothing here yet.</Text>
            <Text dimColor wrap="wrap">This tab is kept for widgets you choose yourself. It stays empty until we decide what goes in it.</Text>
          </Box>
        ),
      })}
    </Box>
  )
}

